'use strict';
(() => {
const D=globalThis.RA.D;
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({wrong,right,reason,errorType});
const Q=(s,prompt,answer,wrong1,wrong2,explain,errorType='meaning')=>({s,prompt,answer,wrong1,wrong2,explain,errorType});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:`Etymonline: https://www.etymonline.com/word/${w.toLowerCase().replaceAll(' ','-')}`});
const P=(w,origin,contexts,mistake,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(contexts)?contexts:[contexts],mistakes:[mistake],quiz:qs.map((q,i)=>({id:`${w}.q${i+1}`,senseId:`${w}.s${q.s}`,prompt:q.prompt,answer:q.answer,options:[q.answer,q.wrong1,q.wrong2],explain:q.explain,errorType:q.errorType,type:'辨义与用法'}))});
P('serigraphy','Serigraphy was formed for silk-screen printing from Latin sericum “silk” and the Greek-derived element -graphy “writing or recording”; it is a stencil printmaking method.',C('serigraphy.s1','艺术','The artist used serigraphy to print vivid layers of colour through a mesh stencil.','艺术家用丝网版画工艺透过网版印出了鲜艳的多层色彩。','serigraphy print/process; produce a serigraph','名词，指借助网版和模板刮印油墨的版画工艺。','ink passes through stencil mesh.','艺术'),M('The artist made the serigraphy by carving a block of stone and pressing it onto paper.','The artist made the serigraphy by pushing ink through a stencil on a mesh screen.','石版雕刻是另一种印刷方法；serigraphy采用网版和模板。','distinction'),[Q(1,'Serigraphy is a printmaking method that uses…','a stencil on a mesh screen','a needle and thread','a carved stone sculpture','The defining equipment is a stencil and mesh screen.','meaning'),Q(1,'An artist choosing serigraphy can…','lay down vivid colours through a screen','sew coloured fabric into a garment','scuttle a ship','Serigraphy transfers ink through a screen.','context'),Q(1,'Which phrase is natural?','a serigraphy print','a serigraphy to printed','a serigraphic printmakingly','Serigraphy names the printing technique.','grammar'),Q(1,'The element -graphy contributes the idea of…','writing or recording','serving food','being serious','The term combines the silk-related element with -graphy.','word-formation')]);
P('serious','From Latin serius “weighty, important,” serious describes something bad or dangerous, or a person who is not joking and gives a matter careful thought.',[C('serious.s1','健康','The doctor said the infection was serious and needed immediate treatment.','医生说感染很严重，需要立即治疗。','a serious illness/injury/problem','形容词，表示情况严重、危险或后果重大。','doctor emphasizes danger.','健康'),C('serious.s2','通用','Are you serious about moving abroad, or were you only joking?','你是真的认真考虑移居国外，还是只是在开玩笑？','be serious about + noun/gerund','也表示不是开玩笑，或认真对待某事。','question contrasts joke with intent.','通用')],M('The doctor described the life-threatening infection as serious, meaning it was harmless and needed no care.','The doctor described the life-threatening infection as serious and arranged immediate treatment.','危及生命的感染并非无害，也不能因严重而不治疗。','meaning'),[Q(1,'A serious infection is…','bad or dangerous','a joke with no consequence','a small serving of food','Serious sense 1 means severe or dangerous.','meaning'),Q(2,'“Are you serious about moving?” asks whether you…','really intend to move','are being treated for an infection','are setting a table','This sense contrasts genuine intention with joking.','context'),Q(1,'Which phrase is natural?','a serious injury','a seriousfully injury','a seriousness injury','Serious is an adjective modifying injury.','grammar'),Q(2,'Which sentence uses serious to mean not joking?','She was serious about applying for the job.','The storm caused serious damage.','His illness became serious.','A genuine intention rather than a joke is the second sense.','meaning')]);
P('seriously','Seriously is formed from serious + -ly; it describes an action or effect causing major harm, or an attitude of full attention and genuine intent.',[C('seriously.s1','通用','The storm seriously damaged the roof and flooded the attic.','风暴严重损坏了屋顶，还淹了阁楼。','seriously damage/hurt/affect','副词表示造成严重后果或伤害。','roof damaged substantially.','通用'),C('seriously.s2','通用','She took the safety warning seriously and stopped the machine.','她认真对待安全警告，关停了机器。','take something seriously; speak seriously','也表示认真看待、全神贯注或并非开玩笑。','warning changes behaviour.','通用')],M('The storm seriously damaged the roof, leaving it completely untouched and in perfect condition.','The storm seriously damaged the roof, tearing away several panels.','毫发无损的屋顶不可能受到严重损坏。','meaning'),[Q(1,'The storm seriously damaged the roof means it…','caused major damage','left the roof completely untouched','moved the roof to a new house','Seriously describes the great degree of harm.','meaning'),Q(2,'Take a warning seriously means…','give it full attention and act on it','treat it as a joke','turn it into a sermon','This phrase means respond as though the warning matters.','context'),Q(1,'Which sentence uses the adverb correctly?','They seriously considered the risk.','They serious consideredly the risk.','They consideration serious the risk.','Seriously modifies the verb considered.','grammar'),Q(2,'If he is speaking seriously, he is…','not joking and giving the matter attention','speaking in a way that causes injury','describing a serious injury only','The second sense concerns attitude rather than degree of harm.','meaning')]);
P('seriousness','Seriousness is formed from serious + -ness; it names a thoughtful, earnest manner or the degree of danger or importance of a problem.',[C('seriousness.s1','态度','The committee discussed the proposal with seriousness and avoided jokes.','委员会认真讨论了提案，没有开玩笑。','with seriousness; show seriousness about + issue','名词，指严肃认真的思考或举止。','discussion is earnest.','态度'),C('seriousness.s2','健康','The report made clear the seriousness of the chemical leak.','报告说明了化学品泄漏的严重程度。','the seriousness of + problem/illness','也指问题、事件或疾病有多严重、重要。','report assesses danger.','健康')],M('The report showed the seriousness of the leak by proving that no chemical escaped and no one faced any risk.','The report showed the seriousness of the leak by documenting toxic exposure and injuries.','没有泄漏和风险不能说明事件严重。','meaning'),[Q(1,'Discussing a proposal with seriousness means discussing it…','earnestly and thoughtfully','as a joke','with no attention at all','Seriousness sense 1 is an earnest manner.','meaning'),Q(2,'The seriousness of an illness refers to…','how severe or dangerous it is','whether the patient can serve dinner','the patient’s sense of humour','Sense 2 measures severity or importance.','context'),Q(1,'Which phrase is natural?','the seriousness of the problem','the serious of problemness','the seriousness to problemly','Of introduces the issue whose severity is assessed.','grammar'),Q(1,'Which suffix forms seriousness from serious?','-ness','-ly','-er','The suffix -ness makes an abstract noun.','word-formation')]);
P('sermon','From Latin sermo “speech, conversation,” through Old French sermon; a sermon is a religious talk or, informally, a long lecture about how people should behave.',[C('sermon.s1','宗教','The minister delivered a short sermon about forgiveness during Sunday service.','牧师在周日礼拜中讲了一篇关于宽恕的简短布道。','deliver/preach a sermon; sermon on + topic','名词，指宗教仪式中牧师或神职人员的讲话。','minister speaks during worship.','宗教'),C('sermon.s2','口语','My brother gave me a sermon about keeping the kitchen clean.','我哥哥就保持厨房整洁的事给我说教了一大通。','give someone a sermon about + behaviour','非正式地指长篇训诫别人应如何行事。','long lecture about chores.','口语')],M('The minister delivered a sermon at the religious service, but the talk was a restaurant menu with no speech.','The minister delivered a sermon by speaking to the congregation about forgiveness.','菜单不是牧师在礼拜中发表的讲话。','meaning'),[Q(1,'A minister gives a sermon during…','a religious service','a computer repair','a court sewer inspection','Sermon sense 1 is a religious talk.','meaning'),Q(2,'If a parent gives a teenager a sermon about chores, the parent…','lectures at length about how to behave','serves a meal','makes a short neutral announcement only','The informal sense is a long moralizing talk.','context'),Q(1,'Which phrase is natural?','preach a sermon on forgiveness','preach a sermon at forgivenessing','sermonize a preach on of','On introduces the sermon topic.','grammar'),Q(1,'Sermon came through French from Latin sermo, meaning…','speech or conversation','a mesh screen','a servant','The Latin ancestor referred to speech or conversation.','word-formation')]);
P('sermonize','Sermonize is formed from sermon + -ize; it means deliver a religious sermon or speak at length about how people ought to behave.',C('sermonize.s1','通用','He sermonized about honesty for half an hour instead of answering the question.','他没有回答问题，而是围绕诚实说教了半小时。','sermonize about + topic; sermonize to + audience','动词，指发表冗长的宗教讲话或训诫。','long moral lecture.','通用'),M('The coach sermonized about sportsmanship in one brief sentence and then let the players speak.','The coach sermonized about sportsmanship at length without allowing discussion.','一句简短的话不符合sermonize的长篇说教特点。','distinction'),[Q(1,'To sermonize about honesty is to…','speak at length about how people should behave','silently sew a garment','screen a film','Sermonize means preach or moralize at length.','meaning'),Q(1,'Which sentence uses sermonize naturally?','He sermonized to the team about discipline.','He sermonize the team discipline yesterday.','He sermonized by a settee only.','Sermonize can be followed by to + audience and about + topic.','grammar'),Q(1,'A friend keeps giving long moral lectures. The friend is…','sermonizing','scrapbooking','searing','The word fits extended advice about conduct.','context'),Q(1,'Sermonize is formed from sermon plus…','-ize','-ness','-er','-ize forms a verb meaning deliver sermons or moralize.','word-formation')]);
P('serpent','From Latin serpens “snake,” from serpere “to creep”; serpent is a literary or formal word for a large, long-bodied reptile without legs.',C('serpent.s1','动物','A serpent slid through the grass and disappeared beneath the stone wall.','一条蛇滑过草丛，消失在石墙下。','a serpent in + place; a coiled serpent','名词，常用于文学或正式语境，指蛇类爬行动物。','long reptile moves through grass.','动物'),M('The guide called the serpent a legged mammal with fur and hooves.','The guide called the serpent a long-bodied reptile with no legs.','serpent是无足爬行动物，不是有毛有蹄的哺乳动物。','distinction'),[Q(1,'A serpent is…','a long-bodied reptile with no legs','a mammal with hooves','a server in a restaurant','Serpent is a formal or literary word for a snake.','meaning'),Q(1,'In a story, a serpent may…','coil in the grass','deliver a meal to a table','turn a screw','The image fits a snake-like reptile.','context'),Q(1,'Which phrase is natural?','a serpent slithered through the grass','a serpent served the grass a meal','a serpent of the grassly','Through introduces the reptile’s path.','grammar'),Q(1,'Serpent comes from Latin serpens, related to a verb meaning…','creep','serve food','sow seeds','The Latin root referred to crawling or creeping.','word-formation')]);
P('serpentine','From Latin serpentinus, from serpens “snake”; serpentine describes a shape or movement that winds and twists like a serpent.',C('serpentine.s1','地理','A serpentine road wound up the mountain in a series of sharp bends.','一条蜿蜒的山路以连续急弯盘旋而上。','a serpentine road/path/curve','形容词，指弯曲盘绕、像蛇行一样的。','road twists up slope.','地理'),M('The serpentine road ran straight for twenty kilometres without a single bend.','The serpentine road twisted up the mountain through a series of bends.','完全笔直的道路不符合弯曲盘绕的serpentine。','meaning'),[Q(1,'A serpentine road is…','curving and twisting like a snake','perfectly straight','made of a serving tray','Serpentine describes winding form or motion.','meaning'),Q(1,'Which object could be serpentine?','a path with repeated hairpin bends','a flat square plate','a straight vertical shaft','Repeated bends make the path snake-like.','context'),Q(1,'Which phrase is natural?','a serpentine path through the hills','a serpentine pathly straight','a path to serpentine by hillsing','Serpentine is an adjective modifying path.','grammar'),Q(1,'Serpentine derives from a Latin word for…','snake','screen','sermon','The adjective refers to the shape or movement of a serpent.','word-formation')]);
P('serrate','From Latin serratus “notched like a saw,” from serra “saw”; serrate describes an edge with sharp, forward-pointing teeth.',C('serrate.s1','植物','The serrate leaf has small teeth that point toward its tip.','这片锯齿状叶子的细齿朝向叶尖。','a serrate edge/leaf; serrate margins','形容词，指边缘有向前尖齿，类似锯齿。','leaf margin toothed.','植物'),M('The botanist described the leaf as serrate even though its edge was perfectly smooth and had no teeth.','The botanist described the leaf as serrate because its edge had sharp, forward-pointing teeth.','光滑无齿的边缘不是serrate。','meaning'),[Q(1,'A serrate leaf has…','sharp teeth along its edge','a completely smooth edge','a long written sermon','Serrate means saw-toothed.','meaning'),Q(1,'The teeth on a serrate leaf point…','forward toward the tip','back toward the root only','down into the soil','The source sense specifies forward-pointing teeth.','context'),Q(1,'Which phrase is natural?','a serrate leaf margin','a serrately leaf margin','a serrate of margining','Serrate modifies the edge or margin.','grammar'),Q(1,'Serrate is related to Latin serra, meaning…','saw','servant','seed','The word refers to a saw-like edge.','word-formation')]);
P('serrated','Serrated is the past-participle adjective of serrate; it means notched with a row of tooth-like points along an edge.',C('serrated.s1','工具','Use a serrated knife to cut the crusty bread without crushing it.','用锯齿刀切硬皮面包，就不会把面包压扁。','a serrated knife/blade/edge','形容词，指边缘排列着齿状缺口或尖齿。','blade teeth grip crust.','工具'),M('The serrated knife had a completely smooth, toothless blade that could not grip the crust.','The serrated knife had a row of teeth that gripped the crust as it cut.','锯齿刀有齿状边缘，不是光滑无齿的刀刃。','meaning'),[Q(1,'A serrated knife has…','a tooth-like edge','a perfectly smooth edge','a mesh screen','The adjective means notched with teeth along an edge.','meaning'),Q(1,'Why use a serrated blade on crusty bread?','Its teeth can grip and cut the crust.','It contains no cutting edge.','It serves food at a table.','The toothed edge helps cut a hard crust.','context'),Q(1,'Which phrase is natural?','a serrated edge','a serratedly edge','a serration edgeing','Serrated is an adjective modifying edge.','grammar'),Q(1,'Serrated is related to the adjective…','serrate','sermon','seriousness','Serrated is the participial form of serrate.','word-formation')]);
P('serum','From Latin serum “whey, watery fluid”; serum is the clear liquid part of blood or a preparation derived from blood to treat illness.',C('serum.s1','医学','The patient received a serum containing antibodies against the virus.','病人接受了含有抗病毒抗体的血清治疗。','blood serum; a serum against + disease','名词，指血液的澄清液体部分或用于治疗的血液制剂。','antibodies in treatment.','医学'),M('The doctor gave the patient a serum, a solid bone that contains no liquid from blood.','The doctor gave the patient a serum, a liquid prepared from blood and containing antibodies.','serum是血液中的液体部分或相关制剂，不是固体骨骼。','meaning'),[Q(1,'Serum is…','the clear liquid part of blood or a related treatment liquid','a type of bone','a seaweed seasoning','Serum refers to a blood-derived liquid.','meaning'),Q(1,'A serum against a virus may contain…','antibodies','sewing needles','a mesh screen','Antibodies can be present in therapeutic serum.','context'),Q(1,'Which phrase is natural?','a serum against the virus','a serum for virusly against','serum the virus into','Against identifies the disease targeted by the preparation.','grammar'),Q(1,'Serum comes from a Latin word meaning…','whey or watery fluid','saw','service','The Latin source referred to whey or a clear liquid.','word-formation')]);
P('servant','From Old French servant, from Latin servientem, present participle of servire “serve”; a servant is a household worker or someone who works for government or the public.',[C('servant.s1','职业','The household employed a servant to cook and care for the children.','这户人家雇了一名仆人做饭并照看孩子。','a domestic/household servant; servant to + employer','名词，指受雇在私人家庭工作的人。','worker serves household.','职业'),C('servant.s2','公共事务','Civil servants prepared the documents for the minister’s visit.','公务员为部长来访准备了文件。','a civil/public servant; servant of the state','也指为政府或公众工作的人员。','government employees prepare documents.','公共事务')],M('The household servant was the family’s employer and paid the family to cook for him.','The household servant was employed by the family to cook and care for the home.','servant是受雇工作者，不是雇主。','distinction'),[Q(1,'A household servant is…','a person paid to work in another home','the person who owns every household','a person who runs a screen','Servant sense 1 is a domestic worker.','meaning'),Q(2,'Civil servants work for…','the government or public','a private restaurant only','a ship’s engine','The second sense names public-sector workers.','context'),Q(1,'Which phrase is natural?','a servant of the state','a servant to the statehooding','a serving of state','Servant of the state is a standard description.','collocation'),Q(1,'Servant is related to Latin servire, meaning…','serve','serrate','set aside','The Latin verb means serve.','word-formation')]);
P('serve','From Old French servir and Latin servire “be a servant”; serve means work for someone or an organization, provide food, start play by hitting a ball, spend a prison term, or function as something.',[C('serve.s1','工作','She served in the navy for six years before becoming a teacher.','她在海军服役六年后成为一名教师。','serve in + organization; serve someone','动词，表示为个人、组织或国家工作。','naval service.','工作'),C('serve.s2','餐饮','Dinner is served at seven, so please be seated by then.','晚餐七点供应，请在那之前入座。','serve food/drink to someone; serve dinner','动词，表示把食物或饮料端给某人。','meal provided.','餐饮'),C('serve.s3','运动','She served an ace in the final game of the match.','她在比赛最后一局发出了一记ACE球。','serve the ball; serve an ace','体育动词，指击球开始一分或一轮比赛。','tennis point begins.','运动'),C('serve.s4','通用','He served six months in prison, and the wooden box will serve as a stool.','他在狱中服刑六个月，而木箱可以当作凳子用。','serve time; serve as + role/function','也可指服刑，或用作、充当某物。','prison term and function.','通用')],M('The waiter served dinner by refusing to bring food or drink to any guest.','The waiter served dinner by bringing the meal to each table.','拒绝上菜不是serve食物。','meaning'),[Q(1,'She served in the navy means she…','worked as a member of the navy','served dinner to sailors','hit a tennis ball','Serve can mean work for an organization or country.','meaning'),Q(2,'Dinner is served at seven means…','the meal is provided at seven','the meal is cancelled at seven','the restaurant’s server leaves at seven','This is the food-provision sense.','context'),Q(3,'In tennis, to serve is to…','hit the ball to begin play','end the match without a point','serve a meal to the umpire','A serve starts a point.','meaning'),Q(4,'The box will serve as a stool means it will…','function as a stool','serve a prison term','be set aside','Serve as means function as.','grammar')]);
P('server','Server is formed from serve + -er; it means a computer that stores and sends information or a restaurant worker who brings food to tables.',[C('server.s1','科技','The web server stores the pages and sends them to users’ browsers.','网络服务器存储网页并将其发送到用户的浏览器。','a web/file server; server stores/sends data','名词，指储存信息并向其他计算机发送数据的设备或程序。','computer supplies pages.','科技'),C('server.s2','餐饮','Our server brought the bread and explained the evening’s specials.','我们的服务员端来面包，并介绍了当晚的特色菜。','ask/tip a server; restaurant server','名词也指在餐厅为顾客上菜的人。','employee brings food.','餐饮')],M('The web server stored no data and could not send information to any other computer.','The web server stored the pages and sent them to users’ computers.','服务器的功能包括存储并提供信息。','meaning'),[Q(1,'A web server…','stores information and sends it to other computers','brings plates to restaurant tables','sews garments','The technology sense is a computer or program serving data.','meaning'),Q(2,'A restaurant server is…','a worker who brings food to tables','a computer that stores websites','a person who receives a sermon','The restaurant sense names the service worker.','context'),Q(1,'Which phrase is natural?','the server went down','the server served downing','the server at went downly','A server can go down when it stops operating.','collocation'),Q(1,'Server is formed from serve plus…','-er','-ness','-al','The suffix -er can name a person or device that serves.','word-formation')]);
P('service','From Old French service and Latin servitium, from servus “servant”; service means helping work, a public supply system, maintenance, a religious meeting, or scheduled transport.',[C('service.s1','服务','The hotel is known for its friendly service and quick response to requests.','这家酒店以服务友好、回应客人需求迅速而闻名。','customer/public service; provide a service','名词，指帮助他人或为他人做事的工作。','staff assist guests.','服务'),C('service.s2','公共设施','The water service was interrupted for two days after the pipe burst.','管道爆裂后，供水服务中断了两天。','water/bus/electricity service','也指向公众供应水、电、交通等的系统。','public water supply stops.','公共设施'),C('service.s3','维修','The car needs a full service before the long journey.','这辆车在长途旅行前需要全面保养。','have a car serviced; a full service','名词，指保持机器或车辆良好状态的维护工作。','vehicle maintenance.','维修'),C('service.s4','宗教','The families attended a Sunday service at the village church.','这些家庭参加了村里教堂的周日礼拜。','a church/religious service; hold a service','名词，指基督教礼拜或相关仪式。','worship meeting.','宗教'),C('service.s5','交通','A free service runs from the station to the campus every half hour.','每半小时有一班免费短途接驳车从车站开往校园。','a shuttle/feeder service between + places','也指两地之间定期的短途运输服务。','scheduled short route.','交通')],M('The car went for a service, but the mechanic refused to inspect or maintain any part of it.','The car went for a service, and the mechanic checked and maintained it.','车辆service指维护保养，不是拒绝检查。','meaning'),[Q(1,'Friendly hotel service means…','helpful work provided for guests','a religious meeting only','a settee in the lobby','Service sense 1 is assistance or work for others.','meaning'),Q(2,'A water service is…','a system that supplies water to the public','a mechanic checking a car','a sermon at church','Service can name a public utility system.','context'),Q(3,'A car service involves…','maintenance to keep the vehicle in good condition','selling the vehicle to a server','setting a new price','The maintenance sense concerns vehicle upkeep.','meaning'),Q(5,'A shuttle service between a station and campus…','runs regularly between the two places','holds a church ceremony','repairs the station’s car','Service sense 5 is scheduled short-distance transport.','meaning')]);
P('serviceable','Serviceable is formed from service + -able; it means fit for use and durable even if plain or not attractive.',C('serviceable.s1','日常','The old boots were ugly but still serviceable for another winter.','这双旧靴子虽然难看，但再穿一个冬天仍然够用。','remain/be serviceable; serviceable condition','形容词，表示可用且耐用，尽管外观朴素或老旧。','boots still function.','日常'),M('The serviceable boots fell apart immediately and could not be worn or repaired.','The serviceable boots were plain but sturdy enough to wear.','完全不能穿也无法修理的鞋不是serviceable。','meaning'),[Q(1,'Serviceable boots are…','fit for use and reasonably durable','beautiful but unusable','a type of computer server','Serviceable means usable, often despite a plain appearance.','meaning'),Q(1,'Which item is serviceable?','an old coat that is plain but still keeps out rain','a torn coat that cannot be worn','a polished sculpture','The first coat remains fit for use.','context'),Q(1,'Which phrase is natural?','in serviceable condition','in serviceably condition','serviceable for conditionly','Serviceable condition describes something usable.','grammar'),Q(1,'Serviceable is formed from service plus…','-able','-ship','-ly','The suffix -able means capable of being used or served.','word-formation')]);
P('serviceman','Serviceman combines service and man; it names a male member of a country’s armed forces. In contemporary neutral wording, service member is often preferred.',C('serviceman.s1','军事','The serviceman was honoured at a ceremony after returning from deployment.','这名军人在部署任务归来后于仪式上受到表彰。','a serviceman in + armed force; servicemen','名词，指一国武装部队中的男性成员。','military member honoured.','军事'),M('The serviceman belonged to the armed forces, but the word means a civilian restaurant worker.','The serviceman belonged to the country’s armed forces.','该词指军人，而非餐厅服务员。','distinction'),[Q(1,'A serviceman is…','a male member of a country’s armed forces','a restaurant server','a person who maintains water service only','The source defines serviceman as an armed-forces member.','meaning'),Q(1,'A serviceman might be honoured after…','returning from military deployment','serving dinner to guests','setting aside a meeting','The military context matches the word’s meaning.','context'),Q(1,'Which phrase is natural?','a serviceman in the navy','a serviceman to the navying','a serving man of food','In the navy identifies the armed force.','grammar'),Q(1,'A gender-neutral alternative to serviceman is often…','service member','serviette','sermonizer','Service member avoids specifying gender.','usage')]);
P('serviette','From French serviette, a diminutive related to servir “serve”; a serviette is a paper or cloth napkin used during a meal.',C('serviette.s1','餐饮','She placed a clean paper serviette beside each plate.','她在每个盘子旁放了一张干净的纸餐巾。','paper/cloth serviette; fold a serviette','名词，指吃饭时用来擦手或护衣的一块纸巾或布巾。','napkin set by plate.','餐饮'),M('She used a serviette at dinner, a heavy metal tool for tightening screws.','She used a serviette at dinner to wipe her hands.','serviette是餐巾，不是螺丝刀。','meaning'),[Q(1,'A serviette is used…','at a meal to wipe hands or protect clothing','to tighten a screw','to connect a sewer pipe','Serviette means a napkin.','meaning'),Q(1,'Which item could be a serviette?','a paper napkin beside a plate','a metal screwdriver','a computer server','A paper napkin is a serviette.','context'),Q(1,'Which phrase is natural?','fold a cloth serviette','serviette a cloth foldingly','fold to serviette at cloth','One can fold a serviette before a meal.','grammar'),Q(1,'Serviette came into English from…','French','Latin directly as a military title','Old Norse','The noun is borrowed from French.','word-formation')]);
P('serving','Serving is formed from serve + -ing; it names an amount of food for one person or the spoon or dish used to distribute food.',[C('serving.s1','饮食','Each serving contains about eight grams of protein.','每份食物含有约八克蛋白质。','a serving of + food; one serving','名词，指一餐中供给一个人的食物量。','nutrition per portion.','饮食'),C('serving.s2','餐饮','Put the large serving beside the bowl so everyone can spoon out rice.','把大号分菜勺放在碗旁，方便大家舀米饭。','a serving spoon/dish','名词也指用于分配食物的大勺或大盘。','utensil for sharing food.','餐饮')],M('The label lists one serving as the amount for one person, but defines it as a spoon used to hand out food.','The label lists one serving as the amount of food for one person.','食物份量与分菜用具是不同义项，不能混为一谈。','distinction'),[Q(1,'One serving of soup is…','the amount intended for one person','a utensil for cutting bread','a unit of electricity','Serving sense 1 is a portion of food.','meaning'),Q(2,'A large serving beside a bowl might be…','a spoon used to give food to people','one person’s meal portion','a sermon','Sense 2 is a serving utensil or dish.','context'),Q(1,'Which phrase is natural?','a serving of rice','a serving riceful of','a rice servingly of','Of introduces the food portion.','grammar'),Q(1,'Which sentence uses serving as a utensil?','Use the serving spoon to pass the vegetables.','Each serving has 200 calories.','The serving size is listed on the label.','The spoon is an object used to distribute food.','meaning')]);
P('sesame','From Greek sesamon, borrowed from an older eastern Mediterranean or Semitic source whose deeper origin is uncertain; sesame is the plant or its tiny edible seed.',[C('sesame.s1','饮食','She sprinkled sesame seeds over the bread before baking it.','烘烤前，她在面包上撒了芝麻。','sesame seeds/oil; sprinkle sesame on + food','名词，指芝麻这种热带植物或它的微小种子。','seeds top bread.','饮食')],M('The baker sprinkled sesame over the bread, using large salty fish instead of tiny seeds.','The baker sprinkled sesame seeds over the bread.','sesame指种子或植物，不是鱼。','meaning'),[Q(1,'Sesame is…','a tropical plant or its tiny edible seeds','a sea mammal','a religious meeting','Sesame names the plant and its seeds.','meaning'),Q(1,'A baker may sprinkle sesame on bread to…','add seeds as a topping','make the bread a seaport','seal the oven shut','Sesame seeds are commonly used as a topping.','context'),Q(1,'Which phrase is natural?','sesame oil','sesame to oiled','oil sesameful','Sesame oil is made from sesame seeds.','collocation'),Q(1,'The deeper source of sesame beyond Greek sesamon is…','uncertain','Old English for servant','Latin for season','The word’s more remote origin is not established with certainty.','word-formation')]);
P('session','From Latin sessio “a sitting,” from sedere “sit”; a session is a period devoted to an activity or a formal meeting or term of a court or school.',[C('session.s1','工作','The recording session lasted all day because the musicians repeated several takes.','录音时段持续了一整天，因为音乐家们反复录了好几遍。','a work/recording/training session','名词，指用于某项活动的一段时间。','activity occupies a period.','工作'),C('session.s2','公共事务','Parliament is in session while lawmakers debate the new budget.','议员辩论新预算期间，议会正在开会。','be in session; hold a session','名词也指正式会议，或法院、学校开会/上课的时段。','formal body meets.','公共事务')],M('The recording session lasted all day, but no recording or other activity took place during it.','The recording session lasted all day while the musicians recorded and reviewed their takes.','session是用于特定活动的时段，不是没有活动的空档。','meaning'),[Q(1,'A recording session is…','a period set aside for recording','a permanent musical instrument','a court decision','Session sense 1 is a block of time for an activity.','meaning'),Q(2,'If Parliament is in session, it is…','meeting to conduct its business','closed for the year','recording a song','Session sense 2 can describe a formal meeting.','context'),Q(1,'Which phrase is natural?','a training session','a training sessionly','a session of train at','Session commonly modifies an activity.','collocation'),Q(2,'A school session may refer to…','a period when the school meets or teaches','the teacher’s computer server','a permanent holiday','The second sense includes a school’s meeting or teaching period.','meaning')]);
P('set','From Old English settan “put, place, cause,” a Germanic verb; set means position or adjust something, cause a state, go below the horizon, a group, or fixed.',[C('set.s1','日常','Set the alarm for six so we can catch the early train.','把闹钟设在六点，这样我们能赶上早班火车。','set a device for + time; set something on/in + place','动词，表示放置某物或调节装置。','alarm adjusted.','日常'),C('set.s2','思维','The unexpected question set the whole class thinking.','这个意外问题让全班都思考起来。','set someone doing/thinking; set something in motion','动词也可表示使某人或某事进入某种状态。','question causes thinking.','思维'),C('set.s3','自然','The sun sets behind the hills earlier in winter.','冬天太阳会更早落到山后。','the sun/moon sets; sunset','不及物动词，指天体落到地平线以下。','sun goes below horizon.','自然'),C('set.s4','日常','She bought a set of glasses for the new kitchen.','她为新厨房买了一套玻璃杯。','a set of + related items','名词，指属于一组、配套的若干物品。','matching glasses together.','日常'),C('set.s5','时间','Lunch is at a set time each day, so the staff can plan their shifts.','每天午餐时间固定，因此员工可以安排班次。','a set time/date/price','形容词，表示确定、不变的。','time fixed in advance.','时间')],M('Set the alarm for six by leaving the time unset and switching the device off.','Set the alarm for six by adjusting its clock and turning it on.','未设定时间且关机不能达到设闹钟的目的。','meaning'),[Q(1,'Set the alarm for six means…','adjust it so it rings at six','put the alarm clock into a group of six','let the sun go below the horizon','Set sense 1 includes adjusting a device.','meaning'),Q(2,'The question set the class thinking means it…','caused the students to think','placed the students on a shelf','fixed an unchanging class time','Set can cause a person or group to enter a state.','context'),Q(3,'The sun sets behind the hills when it…','goes below the horizon','is adjusted with an alarm','joins a group of glasses','This intransitive sense describes sunset.','meaning'),Q(4,'A set of glasses is…','a group of related items','a fixed appointment time','a single unconnected glass','Set as a noun can mean a group or collection.','meaning')]);
P('set apart','Set apart combines set and apart; it means make a person or thing different from others.',C('set apart.s1','区别','Her calm judgment sets her apart from the other candidates.','她沉着的判断力使她与其他候选人区别开来。','set someone/something apart from + group','短语动词，表示使某人或某物显得不同。','quality creates distinction.','区别'),M('Her calm judgment set her apart by making her exactly identical to every other candidate.','Her calm judgment set her apart by making her noticeably different from the other candidates.','使某人与众不同不等于使其完全相同。','meaning'),[Q(1,'A skill that sets one candidate apart…','makes that candidate distinctive','makes every candidate identical','sets the exam aside','Set apart means distinguish from others.','meaning'),Q(1,'Which sentence uses set apart correctly?','Her patience sets her apart from the rest.','Her patience aparts set from the rest.','Her patience sets the rest apart her.','The pattern is set someone apart from a group.','grammar'),Q(1,'A feature that sets a product apart may…','make it noticeably different from competitors','remove it from a shelf for later','make it catch fire','The phrase describes a distinguishing feature.','context'),Q(1,'Which preposition commonly follows “set apart”?','from','under','through','From introduces the people or things it differs from.','collocation')]);
P('set aside','Set aside combines set and aside; it means reserve something for later or postpone/ignore a decision until a later time.',[C('set aside.s1','计划','She sets aside an hour each evening for reading.','她每天晚上都会留出一小时读书。','set aside time/money/space for + purpose','短语动词，指留出资源以备某用途。','time reserved in advance.','计划'),C('set aside.s1','法律','The appeal court set aside the earlier ruling and ordered a new hearing.','上诉法院撤销了先前裁决，并下令重新开庭。','set aside a ruling/decision','也可表示暂时搁置或依法撤销决定。','previous decision overturned.','法律')],M('She set aside money for rent by spending it all on unrelated gifts.','She set aside money for rent by keeping it in a separate account.','把钱全部花掉不是留作之后使用。','meaning'),[Q(1,'Set aside an hour for reading means…','reserve that time for reading','cancel the hour completely','make an hour catch fire','This sense means keep time available for a purpose.','meaning'),Q(1,'An appeal court sets aside a ruling when it…','overturns or cancels the earlier decision','sets the ruling on a table','confirms that nothing can change','The legal sense means overturn a decision.','context'),Q(1,'Which phrase is natural?','set aside money for rent','set money rent aside forly','set aside to rent the money from','For introduces the purpose of the saved resource.','grammar'),Q(1,'Which sentence uses the “reserve” sense?','They set aside a room for visiting researchers.','The court set aside the conviction.','He set up a new company.','Reserving a room for later use is the first sense.','meaning')]);
P('set fire to','Set fire to is a fixed phrase meaning deliberately cause something to start burning.',C('set fire to.s1','安全','Someone set fire to the empty shed, and firefighters arrived within minutes.','有人故意点燃了空棚屋，消防员几分钟内就赶到。','set fire to + building/object','短语动词，表示故意使某物着火。','deliberate ignition.','安全'),M('The witness set fire to the shed by pouring water over every flame until it went out.','The witness set fire to the shed by igniting dry material inside it.','浇水灭火是扑灭火焰，不是点火。','meaning'),[Q(1,'To set fire to a shed is to…','make it start burning','repair its roof','set aside its contents','The phrase means cause something to burn.','meaning'),Q(1,'Which action could set fire to dry leaves?','lighting a match beside them','pouring water over them','sealing them in a metal box','An ignition source can start a fire.','context'),Q(1,'Which phrase is grammatically correct?','set fire to the paper','set the paper fire from to','set fire on the paper to','The fixed pattern is set fire to + object.','grammar'),Q(1,'In this phrase, fire is…','the burning that is deliberately started','a group of related items','a court session','Set fire to means cause a fire.','meaning')]);
P('set off','Set off combines set and off; it means begin a journey or cause an alarm, explosion, or other event to start.',[C('set off.s1','旅行','We set off before dawn to avoid traffic on the mountain road.','我们天亮前就出发了，以避开山路上的交通。','set off for + place; set off on + journey','短语动词，表示开始一段旅程。','travel begins early.','旅行'),C('set off.s2','安全','Smoke from the kitchen set off the building’s fire alarm.','厨房里的烟触发了大楼的火警。','set off an alarm/explosion; set something off','也表示使警报、爆炸等开始发生。','smoke triggers alarm.','安全')],M('They set off for the coast by staying home and never beginning the trip.','They set off for the coast before dawn.','留在家中并未开始旅程。','meaning'),[Q(1,'The family set off for the coast means they…','began their journey there','triggered the car alarm only','cancelled the trip permanently','Set off can mean start a journey.','meaning'),Q(2,'Smoke set off the alarm means smoke…','caused the alarm to start sounding','turned the alarm off','started a journey','The second sense means trigger a device or event.','context'),Q(1,'Which phrase is natural?','set off on a long journey','set on off a journeying','set off to journey by on','Set off on + journey is a common pattern.','grammar'),Q(2,'Which sentence uses set off to mean trigger?','The timer set off the sprinkler system.','We set off at sunrise.','They set off for the station.','The sprinkler being triggered is the second sense.','meaning')]);
P('set up','Set up combines set and up; it means start and organize a business or organization, arrange equipment so it is ready, or frame someone with false evidence.',[C('set up.s1','商业','They set up a small design company after leaving university.','他们大学毕业后创办了一家小型设计公司。','set up a business/organization','短语动词，指创立并开始运营一个组织或企业。','company starts operations.','商业'),C('set up.s2','技术','The engineers set up the machines before the safety test.','安全测试前，工程师把机器安装并调试到位。','set up equipment/furniture','也指摆放设备或家具使其可以使用。','equipment prepared.','技术'),C('set up.s3','法律','False papers made it look as if the driver had stolen the car; he had been set up.','伪造文件让人以为司机偷了车；他是被人陷害的。','set someone up with + false evidence','也指安排虚假情形使某人显得有罪。','false evidence frames person.','法律')],M('The investigators set him up by collecting genuine evidence proving he had committed the crime.','The investigators set him up by planting false evidence to make him appear guilty.','真实证据不是陷害所需的伪造情形。','distinction'),[Q(1,'Set up a company means…','start and organize it','cancel it before launch','serve it at dinner','This sense means establish a business.','meaning'),Q(2,'Set up the machines before a test means…','arrange them so they are ready to use','sell them for scrap','start a journey','The equipment sense is preparation and installation.','context'),Q(3,'Someone was set up with false papers means…','a false situation was arranged to make them look guilty','they were hired to work in a restaurant','they set aside a room','Set up can mean frame someone.','meaning'),Q(1,'Which phrase is natural?','set up a small business','set a small business uply','set up to small business from','Set up takes the organization as its object.','grammar')]);
P('setback','Setback is formed from set back; it names an event that delays progress or makes a situation worse.',C('setback.s1','计划','The injury was a setback, but she returned to training after a month.','这次受伤是个挫折，但她一个月后又恢复了训练。','a major/minor setback; suffer a setback','名词，指阻碍进展或使局势恶化的事情。','injury delays progress.','计划'),M('The unexpected setback accelerated the project and removed every obstacle.','The unexpected setback delayed the project and required a new plan.','setback通常会拖慢进展，不会清除障碍。','meaning'),[Q(1,'An injury that delays training is…','a setback','a service','a settee','Setback is an event that hinders progress.','meaning'),Q(1,'How might a team respond to a setback?','revise its plan after progress is delayed','pretend the delay accelerated everything','set fire to the schedule','A setback can require a revised plan.','context'),Q(1,'Which phrase is natural?','suffer a setback','suffer a set backly','setback to suffer of','Suffer a setback is a common collocation.','collocation'),Q(1,'A setback usually…','delays progress or worsens a situation','starts a journey','sets a fixed time','The word names an obstacle or reversal.','meaning')]);
P('settee','Settee is recorded in English for a long seat with a back and arms; its deeper formation is uncertain.',C('settee.s1','家居','A two-seat settee stood beneath the window in the small sitting room.','小客厅的窗下放着一张双人长椅。','a settee in the sitting room; sit on a settee','名词，指有靠背和扶手、可供多人坐的长座。','long upholstered seat.','家居'),M('The settee was a single-person stool with no back or arms.','The settee was a long upholstered seat with a back and arms.','无靠背、无扶手的单人凳不是settee。','distinction'),[Q(1,'A settee is…','a long seat with a back and arms','a small serving spoon','a vertical mine passage','Settee names a sofa-like seat for two or more people.','meaning'),Q(1,'Where might a settee stand?','in a sitting room beneath a window','inside a sewer pipe','on the seafloor','A settee is household furniture.','context'),Q(1,'Which phrase is natural?','sit on the settee','sit at the setteeing','settee the sit for','On identifies the furniture one sits on.','grammar'),Q(1,'The word’s deeper formation is…','uncertain','certainly a plural of seat','an acronym for a computer','Its earlier origin is not confidently established.','word-formation')]);
P('setting','Setting is formed from set + -ing; it means the location and surroundings of an event or story, or the adjusted position of a device.',[C('setting.s1','文学','The novel’s wartime setting shapes every character’s choices.','小说的战时背景影响了每个角色的选择。','the setting of a story; a rural/wartime setting','名词，指故事或事件发生的地点及周围环境。','story takes place during war.','文学'),C('setting.s2','技术','Turn the oven to a low setting before baking the cake.','烤蛋糕前把烤箱调到较低的档位。','a high/low setting; change the setting','名词也指装置被调到的位置或状态。','oven control selected.','技术')],M('The oven was on a low setting, meaning it was adjusted to its highest possible temperature.','The oven was on a low setting, so it was set to a gentle temperature.','low与最高温度相反。','distinction'),[Q(1,'A novel’s setting is…','the place and surroundings where its events occur','the oven temperature only','the novel’s serviceable cover','Setting sense 1 is a story’s environment.','meaning'),Q(2,'A low oven setting means…','the device is adjusted to a low level','the oven is at its highest heat','the kitchen is a war story','Setting can name an appliance’s selected level.','context'),Q(1,'Which phrase is natural?','the setting of the story','the story settingly of','set the story into setting','Of introduces what the setting belongs to.','grammar'),Q(2,'Which sentence uses setting for a device?','Change the brightness setting on your screen.','The film has a coastal setting.','The setting of the novel is Paris.','Brightness is an adjustable device position.','meaning')]);
P('settle','From Old English setlan “make or become settled”; settle means resolve an argument, establish a home, become calm or sink, or pay a bill.',[C('settle.s1','协商','The neighbors settled the boundary dispute after comparing the old maps.','邻居们对照旧地图后解决了边界争议。','settle a dispute/argument; settle with someone','动词，表示结束争论或最终决定问题。','agreement resolves dispute.','协商'),C('settle.s2','生活','They settled in Canada after several years of moving between countries.','他们在多个国家辗转数年后，定居加拿大。','settle in + place; settle somewhere','动词，指到某地长期居住。','family establishes home.','生活'),C('settle.s3','自然','The dust settled slowly after the workers stopped drilling.','工人停止钻孔后，灰尘慢慢落了下来。','dust/sediment settles; settle down','也指变平静或缓慢沉降。','particles fall.','自然'),C('settle.s4','财务','Please settle the bill before leaving the restaurant.','离开餐厅前请结清账单。','settle a bill/debt/account','动词，表示支付所欠的钱。','payment clears debt.','财务')],M('They settled the bill by leaving the restaurant without paying any of the money they owed.','They settled the bill by paying the amount they owed before leaving.','不付款不能算结清账单。','meaning'),[Q(1,'Settle a dispute means…','end the argument or reach a final decision','move dust into the air','leave a bill unpaid','Settle sense 1 resolves disagreement.','meaning'),Q(2,'They settled in Canada means they…','made a permanent home there','paid an old restaurant bill there','caused a dispute there','This sense means establish residence.','context'),Q(3,'Dust settled after drilling stopped means it…','fell slowly to the ground','rose higher into the air','was written into a sermon','Settle can describe particles sinking.','meaning'),Q(4,'Settle the bill means…','pay the money owed','make the bill more serious','reserve it for next month','Settle has a financial sense meaning pay.','meaning')]);
P('settled','Settled is the past participle of settle; as an adjective it means fixed, agreed, or established after earlier uncertainty.',C('settled.s1','生活','After years of travel, they wanted a settled life in one quiet town.','旅行多年后，他们想在一座安静的小镇过稳定的生活。','a settled life/arrangement; feel settled','形容词，表示已安定、商定或确立。','family wants stability.','生活'),M('After years of uncertainty, the settled arrangement changed every hour and had never been agreed.','After years of uncertainty, the settled arrangement was agreed and remained stable.','不断变化且未商定的安排不是settled。','meaning'),[Q(1,'A settled life is…','stable and established','constantly changing and uncertain','a period of court service','Settled can mean established after instability.','meaning'),Q(1,'A settled arrangement is one that…','has been agreed or fixed','has not yet been discussed','is a type of server','The adjective means fixed or agreed.','context'),Q(1,'Which phrase is natural?','a settled agreement','a settledly agreement','an agreement settledness','Settled is an adjective modifying agreement.','grammar'),Q(1,'Settled is the past participle of…','settle','set aside','serve','The adjective derives from the verb settle.','word-formation')]);
P('settlement','Settlement is formed from settle + -ment; it means an official agreement ending a dispute, a community where people have established homes, or payment of a debt.',[C('settlement.s1','法律','The two companies reached a settlement after months of negotiations.','谈判数月后，两家公司达成了和解协议。','reach/negotiated settlement; settlement between + parties','名词，指结束争端的正式协议。','parties end dispute.','法律'),C('settlement.s2','历史','The first settlement was built beside the river by families arriving from overseas.','最早的定居点是由海外迁来的家庭在河边建立的。','a new/early settlement; settlement on + land','名词，指一群人前去居住的地方。','community builds homes.','历史'),C('settlement.s3','财务','The settlement of the account took three days because the bank needed to verify the transfer.','由于银行需要核实转账，账户结算花了三天。','settlement of a debt/account; final settlement','名词，也指偿清欠款的行为或金额。','payment processed.','财务')],M('The settlement ended the companies’ dispute, but both sides rejected the agreement and continued their lawsuit.','The settlement ended the companies’ dispute after both sides accepted the agreement.','被双方拒绝且诉讼继续的方案没有解决争端。','meaning'),[Q(1,'A legal settlement is…','an official agreement ending a dispute','a new village only','a server maintenance appointment','Settlement sense 1 resolves a conflict.','meaning'),Q(2,'An early settlement beside a river is…','a place where people established homes','an agreement signed by companies','a payment on an account','The historical sense names a community.','context'),Q(3,'Settlement of an account means…','paying or clearing the amount owed','moving into a new town','starting a sermon','The financial sense concerns payment.','meaning'),Q(1,'Which phrase is natural?','reach a settlement between the parties','settlement to reach partying between','reach the settling by parties','One can reach a settlement with or between parties.','grammar')]);
P('settler','Settler is formed from settle + -er; it names a person who moves to live in a place where few people lived before.',C('settler.s1','历史','Early settlers built houses from local stone near the river crossing.','早期定居者在河流渡口附近用当地石材建房。','early/new settlers; settlers in + region','名词，指迁往原先人烟稀少之地定居的人。','newcomers establish homes.','历史'),M('The settler moved to the region, but refused to live there and returned home the same day.','The settler moved to the region and established a home there.','只短暂停留后回去，没有在当地定居。','meaning'),[Q(1,'A settler is someone who…','moves to live in a place where few lived before','visits a town for one afternoon','settles restaurant bills','Settler names a person who establishes a home in a new area.','meaning'),Q(1,'Early settlers might…','build homes from local materials','hold a court session','set off a fire alarm','Building homes suggests establishing a settlement.','context'),Q(1,'Which phrase is natural?','early settlers in the valley','early settled in valleying','settler to early the valley','In introduces the place where they settle.','grammar'),Q(1,'Settler is formed from settle plus…','-er','-ness','-al','The suffix -er names a person who performs an action.','word-formation')]);
P('setup','Setup is the noun form of set up; it means the way parts of a machine or building are arranged, or how people and jobs are organized in a group.',[C('setup.s1','技术','The studio’s new lighting setup makes it easier to film interviews.','工作室的新灯光布置让采访拍摄更方便。','a computer/studio/setup; change the setup','名词，指设备或建筑部件的布置与协作方式。','lights arranged for recording.','技术'),C('setup.s2','组织','The department changed its setup so each team had a clear manager.','部门调整了内部组织架构，让每个团队都有明确的负责人。','the setup of an organization/team','也指组织内部人员和职务的安排方式。','roles reorganized.','组织')],M('The studio’s setup was changed by taking all the lights apart and leaving no equipment arranged.','The studio’s setup was changed by arranging the lights and cameras for the interview.','设备都拆散并未布置成可运行的结构。','meaning'),[Q(1,'A lighting setup is…','the way lights and equipment are arranged','a religious speech','a settled debt','Setup sense 1 is an arrangement of equipment.','meaning'),Q(2,'A department changes its setup when it changes…','how people and jobs are organized','the colour of its office walls only','how the sun sets','This sense concerns an organization’s structure.','context'),Q(1,'Which spelling is the noun?','setup','set up','set-uped','Setup is normally one word as a noun.','spelling'),Q(1,'Which phrase is natural?','the setup of the studio','the studio setupping of','set up of the studio to','Of introduces the place or organization with that arrangement.','grammar')]);
P('seven','From Old English seofon, from Proto-Germanic *sebun; seven is the number after six and before eight.',C('seven.s1','数字','The shelf has seven books, one for each day of the week.','书架上有七本书，一周每天对应一本。','seven people/days/items; seven of + group','基数词，表示六之后的数。','count of seven books.','数字'),M('The shelf has seven books, and the clerk counted six and stopped.','The shelf has seven books, and the clerk counted all seven.','数到六就停止无法确认数量为七。','meaning'),[Q(1,'Seven is the number…','after six and before eight','after seventeen','equal to seventy','Seven follows six.','meaning'),Q(1,'If seven days each have one book, how many books are there?','seven','six','seventeen','One item for each of seven days gives seven items.','context'),Q(1,'Which spelling is correct?','seven','seveen','sevent','Seven is spelled s-e-v-e-n.','spelling'),Q(1,'Seven is a…','cardinal number','verb meaning settle','noun for a serving spoon','It names a quantity, not an order in a series.','grammar')]);
P('seven days','Seven days combines the number seven with days; it names a period lasting one full week.',C('seven days.s1','时间','The replacement part should arrive within seven days of your order.','替换零件应在下单后七天内送到。','within/in seven days; seven days from + date','名词短语，表示持续七天的一段时间。','delivery period.','时间'),M('The repair took seven days, but it was finished after only two hours.','The repair took seven days from start to finish.','两小时不是七天。','meaning'),[Q(1,'Seven days is a period of…','one week','one month','seventeen weeks','Seven days make a week.','meaning'),Q(1,'“Arrive within seven days” means arrive…','no later than seven days from now or the stated date','exactly seven months later','before the order was placed','Within sets the maximum duration.','context'),Q(1,'Which phrase is natural?','within seven days','within seventh days','within seven dayly','The plural noun days follows seven.','grammar'),Q(1,'Seven days combines seven with the plural of…','day','date','dawn','The phrase names a length of time measured in days.','word-formation')]);
P('seventeen','From Old English seofontyne, formed from seven and ten; seventeen is the number equal to ten plus seven.',C('seventeen.s1','数字','She is seventeen and will turn eighteen next spring.','她十七岁，明年春天就满十八岁。','seventeen years old; seventeen of + items','基数词，表示十加七。','age is 17.','数字'),M('The box contains seventeen screws, but the mechanic counted only ten and said the total was seventeen.','The box contains seventeen screws, and the mechanic counted ten plus seven.','只数十颗不等于十七颗。','meaning'),[Q(1,'Seventeen equals…','ten plus seven','seven times ten','seventy minus one','Seventeen is 10 + 7.','meaning'),Q(1,'A person who is seventeen will turn eighteen…','after one more year','after one more day','after seven decades','Seventeen is one year before eighteen.','context'),Q(1,'Which spelling is correct?','seventeen','seventen','seventeene','Seventeen is spelled with teen after seven.','spelling'),Q(1,'Seventeen is a…','cardinal number','ordinal number','verb meaning settle','It counts quantity rather than position.','grammar')]);
P('seventeenth','Seventeenth is formed from seventeen + -th; it is the ordinal number 17 in a sequence.',C('seventeenth.s1','数字','Her appointment is on the seventeenth, the day after the sixteenth.','她的预约在十七日，也就是十六日的第二天。','the seventeenth day/person; on the seventeenth','序数词，指序列中排第十七。','date follows sixteenth.','数字'),M('She finished seventeenth in the race but was the first person to cross the line.','She finished seventeenth in the race, behind sixteen other competitors.','第一名与第十七名次不相同。','meaning'),[Q(1,'The seventeenth item is…','number 17 in order','a total of 17 items','the number 70','Seventeenth is an ordinal position.','meaning'),Q(1,'If the sixteenth day is Monday, the seventeenth is…','the next day','sixteen days earlier','the seventh day of a month by definition','Ordinal 17 follows ordinal 16.','context'),Q(1,'Which spelling is correct?','seventeenth','seventieth','seventeeneth','Seventeenth is the ordinal form of seventeen.','spelling'),Q(1,'The suffix -th in seventeenth marks…','ordinal position','a person who serves','a fixed setting','-Th forms ordinal numbers.','word-formation')]);
P('seventh','From Old English seofoþa, from seven + an ordinal suffix; seventh means number 7 in order or one of seven equal parts.',[C('seventh.s1','数字','July is the seventh month of the year, after June.','七月是一年中的第七个月，排在六月之后。','the seventh day/month/person','序数词，指序列中排第七。','month order.','数字'),C('seventh.s2','数学','Only a seventh of the work was complete when the deadline changed.','截止日期变更时，工作只完成了七分之一。','a seventh of + whole','名词也可表示七等份中的一份。','one of seven equal shares.','数学')],M('July is the seventh month, but it comes immediately after August.','July is the seventh month, after June and before August.','七月排在六月之后，不在八月之后。','meaning'),[Q(1,'The seventh month of the year is…','July','June','September','July is number seven in the month sequence.','meaning'),Q(2,'A seventh of a cake is…','one of seven equal pieces','the whole cake','one of seventeen cakes','The fractional sense is one equal part out of seven.','context'),Q(1,'Which phrase is natural?','the seventh floor','the seven floor','the seventhly floor','Seventh is the ordinal adjective before floor.','grammar'),Q(1,'Which sentence uses seventh as a fraction?','A seventh of the budget was spent.','She finished seventh.','July is the seventh month.','A seventh of names one of seven equal parts.','meaning')]);
P('seventieth','Seventieth is formed from seventy + -th; it means number 70 in order or one of seventy equal parts.',[C('seventieth.s1','数字','Their office was on the seventieth floor of the new tower.','他们的办公室在新塔楼的第七十层。','the seventieth floor/day/person','序数词，指序列中排第七十。','floor number.','数字'),C('seventieth.s2','数学','The gap was no bigger than a seventieth of a millimetre.','这道缝隙还不到一毫米的七十分之一。','a seventieth of + whole','名词，表示七十等份中的一份。','tiny fraction.','数学')],M('Their office was on the seventieth floor, which the building plan labels as floor 17.','Their office was on the seventieth floor, the floor numbered 70.','seventieth是序数70，不是17。','meaning'),[Q(1,'The seventieth floor is…','floor number 70','floor number 17','one of seven floors','Seventieth is ordinal 70.','meaning'),Q(2,'A seventieth of a millimetre is…','one equal part out of seventy','seventy whole millimetres','one of seven equal parts','The fractional sense is one of 70 equal parts.','context'),Q(1,'Which spelling is correct?','seventieth','seventeenth','seventyth','Seventieth is the ordinal form of seventy.','spelling'),Q(1,'The suffix -th in seventieth marks…','ordinal order','a person who serves','a condition of being serious','The suffix forms the ordinal number.','word-formation')]);
P('seventy','From Old English seofontig, a Germanic formation based on seven; seventy is the number equal to seven times ten.',C('seventy.s1','数字','The bus can carry seventy passengers when every seat is occupied.','每个座位都坐满时，这辆公交车能载七十名乘客。','seventy people/years; in one’s seventies','基数词，表示七乘十。','bus capacity.','数字'),M('The bus carried seventy passengers, but the manifest listed only seven people.','The bus carried seventy passengers, and the manifest listed all seventy.','七与七十相差十倍。','meaning'),[Q(1,'Seventy is equal to…','seven times ten','seventeen plus one','seven times one','Seventy means 70.','meaning'),Q(1,'A bus with seventy seats can hold…','70 passengers','17 passengers','7 passengers','The number states its full capacity.','context'),Q(1,'Which spelling is correct?','seventy','seventee','seventyeth','Seventy is spelled s-e-v-e-n-t-y.','spelling'),Q(1,'Seventy is a…','cardinal number','ordinal number','verb meaning to cut','It names a quantity, not a position.','grammar')]);
P('sever','From Old French severer, from Latin separare “separate”; sever means cut through so a part comes away or end a relationship completely.',[C('sever.s1','工具','The blade severed the rope, and the load dropped safely onto the platform.','刀刃割断了绳子，货物安全地落在平台上。','sever a rope/limb; sever something from + whole','动词，指割断使一部分脱离。','rope cut apart.','工具'),C('sever.s2','关系','The two firms severed all business ties after the failed merger.','合并失败后，两家公司彻底断绝了商业关系。','sever ties/relations with + person/group','也指突然且彻底地结束关系或联系。','business links ended.','关系')],M('The blade severed the rope, leaving every strand completely connected and intact.','The blade severed the rope, cutting it through so the ends came apart.','切断的结果是分离，不会仍完整连接。','meaning'),[Q(1,'To sever a rope is to…','cut through it so its parts separate','tie it more tightly','settle a bill','Sever means cut through and detach.','meaning'),Q(2,'A firm that severs ties with another firm…','ends its relationship with it completely','signs a new partnership with it','sets up a server','The figurative sense is a complete break in relations.','context'),Q(1,'Which phrase is natural?','sever ties with a partner','sever a partner by ties to','severing ties withness','With introduces the person or group links are ended with.','grammar'),Q(1,'Sever is related to Latin separare, meaning…','separate','serve','set','The word traces to a verb meaning separate.','word-formation')]);
P('several','From Anglo-French several, related to Latin separalis “separate”; several means more than two but not many, or distinct and separate.',[C('several.s1','数量','I have visited the museum several times, but I still find new details.','我去过这家博物馆好几次，但仍能发现新的细节。','several people/times/things','限定词，表示多于两个但数量不大。','a handful of visits.','数量'),C('several.s2','分别','After the meeting, the colleagues went their several ways.','会后，同事们各自走向不同方向。','go/take one’s several ways','形容词，表示彼此分开或不同。','people separate.','分别')],M('I visited the museum several times, meaning exactly once and never again.','I visited the museum several times, meaning more than twice.','several表示多个，不是只一次。','meaning'),[Q(1,'Several visits means…','more than two visits, but not a large number','exactly one visit','seventy visits','Several is an indefinite quantity greater than two.','meaning'),Q(2,'They went their several ways means they…','went in separate directions','all went together along one path','reached a settlement','Several can mean separate or distinct.','context'),Q(1,'Which sentence is natural?','Several students asked questions.','Several student asked questionss.','A several of student asked.','Several can directly modify a plural count noun.','grammar'),Q(2,'Which use means “separate”?','They followed their several paths home.','I waited several minutes.','Several books were missing.','Several paths contrasts with one shared path.','meaning')]);
P('severe','From Latin severus “strict, serious”; severe means very bad or serious, or strict and not kind.',[C('severe.s1','健康','The storm caused severe damage to homes along the coast.','风暴对沿海住宅造成了严重损坏。','severe damage/illness/weather','形容词，表示坏到严重或危险的程度。','homes badly damaged.','健康'),C('severe.s2','教育','The teacher was severe but fair when students ignored the safety rules.','学生无视安全规则时，这位老师态度严厉但公正。','a severe teacher/penalty; severe with + person','也表示严格、不宽容或不温和。','teacher enforces rules strictly.','教育')],M('The storm caused severe damage, yet every home remained untouched and fully intact.','The storm caused severe damage, destroying roofs and flooding homes.','房屋完好无损不符合严重破坏。','meaning'),[Q(1,'Severe storm damage is…','very serious or extensive','a tiny harmless mark','a set of glasses','Severe means very bad or serious.','meaning'),Q(2,'A severe teacher is…','strict and not especially gentle','always joking and lenient','a server at a restaurant','The second sense describes strict behavior.','context'),Q(1,'Which phrase is natural?','severe weather','severely weather','a severity weather','Severe is an adjective modifying weather.','grammar'),Q(2,'Which sentence uses severe to mean strict?','The judge gave a severe warning for repeated misconduct.','The severe storm damaged the pier.','Her illness became severe.','A strict warning reflects the second sense.','meaning')]);
P('severely','Severely is formed from severe + -ly; it means to an extreme or serious degree, or in a strict and harsh manner.',[C('severely.s1','通用','The roof was severely damaged when a tree fell across it.','一棵树倒在屋顶上，造成了严重损坏。','severely damaged/injured/affected','副词表示严重或极端的程度。','roof suffers major harm.','通用'),C('severely.s2','行为','The judge spoke severely to the witness who refused to answer.','证人拒绝回答时，法官严厉地对他说话。','speak/look/punish severely','副词也表示以严厉、不留情的方式。','judge uses stern tone.','行为')],M('The roof was severely damaged, but not one tile was cracked, moved, or harmed.','The roof was severely damaged, with several tiles torn away by the falling tree.','没有任何损伤不符合severely damaged。','meaning'),[Q(1,'Severely damaged means damaged…','to a serious or extreme degree','not at all','only in a gentle manner','Severely indicates a high degree of harm.','meaning'),Q(2,'The judge spoke severely means the judge spoke…','in a strict, harsh manner','with a cheerful joke','about a set of chairs','This adverbial sense describes tone or manner.','context'),Q(1,'Which sentence is grammatical?','The storm severely damaged the roof.','The storm severe damaged the roof.','The storm severity damagedly the roof.','Severely is the adverb modifying damaged.','grammar'),Q(2,'Which sentence uses the harsh-manner sense?','She was spoken to severely after breaking the rules.','The injury was severely painful.','The house was severely damaged.','The first describes a strict manner of speaking.','meaning')]);
P('severity','From Latin severitas, from severus “strict, serious”; severity is the degree of seriousness of a problem or the quality of strict or harsh behavior.',[C('severity.s1','健康','Doctors assessed the severity of the infection before choosing a treatment.','医生在选择治疗方案前评估了感染的严重程度。','the severity of + illness/problem/weather','名词，表示疾病、问题或天气的严重程度。','condition assessed.','健康'),C('severity.s2','行为','The students were surprised by the severity of the head teacher’s punishment.','学生们对校长处罚的严厉程度感到惊讶。','the severity of + punishment/criticism','也表示行为或评判上的严格、苛刻或残酷。','punishment is harsh.','行为')],M('The severity of the infection was low because the patient needed intensive care and faced a serious risk.','The severity of the infection was high because the patient needed intensive care and faced a serious risk.','需要重症照护并有重大风险说明严重程度高。','meaning'),[Q(1,'The severity of an infection describes…','how serious it is','how many people work at the hospital','the colour of its medicine','Severity sense 1 measures seriousness.','meaning'),Q(2,'The severity of a punishment refers to…','how strict or harsh it is','how long the school session lasts','how many times a person serves dinner','This sense describes harshness in judgment or behavior.','context'),Q(1,'Which phrase is natural?','the severity of the storm','the severe of stormness','severity to stormly','Of introduces the condition whose seriousness is measured.','grammar'),Q(1,'Severity is related to the adjective…','severe','server','several','Severity is the noun form of severe.','word-formation')]);
P('sew','From Old English siwian, a Germanic verb; sew means join or repair cloth with needle and thread, or close a wound with stitches.',[C('sew.s1','服装','She sewed a button onto the coat before leaving for work.','她上班前把一颗纽扣缝到了外套上。','sew a button/seam; sew something onto + fabric','动词，指用针线制作或修补衣物。','needle joins button.','服装'),C('sew.s2','医学','The doctor sewed up the cut after cleaning it carefully.','医生仔细清洁伤口后把它缝合了。','sew up a wound/cut','也指用缝线闭合伤口。','stitches close cut.','医学')],M('She sewed the button onto the coat using glue and never used a needle or thread.','She sewed the button onto the coat with a needle and thread.','胶水粘贴不是缝纫。','meaning'),[Q(1,'To sew a button onto a coat is to…','attach it with needle and thread','glue it on without stitching','serve it at a table','Sew means make or repair with stitches.','meaning'),Q(2,'The doctor sewed up the cut by…','closing the wound with stitches','opening the cut wider','setting up a server','Sew up describes closing a wound.','context'),Q(1,'Which phrase is natural?','sew a button onto a shirt','sew a shirt buttoning to','sew onto by a button shirt','Onto marks where the button is attached.','grammar'),Q(1,'Sew comes from…','Old English siwian','Latin severitas','Greek sesamon','The verb is an old Germanic word.','word-formation')]);
P('sewage','Sewage is formed from sewer + -age; it means used water and waste from homes or factories that is carried in sewers.',C('sewage.s1','环境','Untreated sewage entered the harbour after the treatment plant lost power.','污水处理厂断电后，未经处理的污水流进了港湾。','raw/untreated sewage; sewage from + source','不可数名词，指由下水道输送的生活或工业废水和污物。','waste water pollutes harbour.','环境'),M('Untreated sewage entered the harbour, but it was clean drinking water with no waste.','Untreated sewage entered the harbour, carrying waste water from the treatment system.','污水不是没有废物的洁净饮用水。','distinction'),[Q(1,'Sewage is…','used water and waste carried in sewers','fresh drinking water from a spring','a cloth used at dinner','Sewage contains waste from homes or factories.','meaning'),Q(1,'Why is untreated sewage entering a harbour a problem?','It can pollute the water with waste.','It makes all seawater fresh.','It forms a serrated blade.','Wastewater can contaminate coastal water.','context'),Q(1,'Which phrase is natural?','untreated sewage entered the river','untreated sewage were a river','sewage to untreateding river','Sewage is an uncountable noun and takes a singular verb.','grammar'),Q(1,'Sewage is related to the noun…','sewer','server','session','Sewage names the waste carried by a sewer system.','word-formation')]);
P('sewer','From Middle English sewer in the sense of a drain or channel; a sewer is an underground pipe or passage carrying waste water away.',C('sewer.s1','公共设施','The old sewer overflowed after heavy rain and flooded the lower street.','暴雨后，老旧下水道溢出，淹了较低处的街道。','a sewer under/beneath + street; sewer pipe','名词，指把污水和废水排走的地下管道或沟渠。','drain carries waste water.','公共设施'),M('The sewer carried waste water, but it was an open dining table where guests ate dinner.','The sewer carried waste water through a channel beneath the street.','sewer是污水管道，不是餐桌。','meaning'),[Q(1,'A sewer is…','a pipe or channel carrying waste water away','a computer that sends information','a room used for a sermon','Sewer sense 1 is part of a drainage system.','meaning'),Q(1,'An old sewer may overflow after…','heavy rain','a sewing lesson','a court session','Rain can overload a drainage channel.','context'),Q(1,'Which phrase is natural?','the sewer beneath the street','the sewer beneathly street','sewering the street of','Beneath identifies the pipe’s underground location.','grammar'),Q(1,'Which waste system does a sewer belong to?','sewerage','serigraphy','several','A sewer is a pipe in a sewerage network.','meaning')]);
P('sewerage','Sewerage is formed from sewer + -age; it means the network and process used to carry away and manage waste water.',C('sewerage.s1','公共设施','The town upgraded its sewerage system after repeated floods.','多次洪水后，小镇升级了污水管网系统。','sewerage system/network; improve sewerage','不可数名词，指输送、排放污水的管网及其处理过程。','town improves waste-water network.','公共设施'),M('The town upgraded its sewerage system by removing every drain and leaving waste water in the streets.','The town upgraded its sewerage system by improving the drains and treatment network.','移除排水设施会使污水留在街上，不是升级系统。','meaning'),[Q(1,'Sewerage refers to…','the network and process for carrying away waste water','the water people drink before use','a dining room service','Sewerage is the waste-water system.','meaning'),Q(1,'A town might upgrade sewerage after…','floods reveal problems in its drainage network','it buys a new settee','a shaman performs a ritual','Flooding can expose sewerage failures.','context'),Q(1,'Which phrase is natural?','the sewerage network','the sewerage networkingly','sewerage to networked of','Sewerage network is a standard phrase.','collocation'),Q(1,'Sewerage is formed from sewer plus…','-age','-ness','-ly','The suffix -age forms a collective or process noun.','word-formation')]);
P('sex','From Latin sexus “male or female,” sex can mean biological classification as male or female or sexual activity.',[C('sex.s1','生物','The form asks patients to state their sex for the medical record.','表格请患者填写其生理性别，以便记录病历。','biological sex; sex assigned at birth','名词，指生理上被归为男性或女性这一属性。','medical form records category.','生物'),C('sex.s2','健康','The clinic provides confidential advice about sex and reproductive health.','诊所提供有关性行为和生殖健康的保密咨询。','talk about/have sex; sex education','名词，也指性行为。','clinic discusses sexual activity.','健康')],M('The medical form asks for sex, but the patient writes the name of a favourite food instead of the requested biological information.','The medical form asks for sex, and the patient provides the relevant biological information.','此处表格需要生理信息，不是饮食偏好。','context'),[Q(1,'On a medical form, sex may refer to…','biological classification as male or female','a person’s favourite meal','a computer’s server role','Sex sense 1 is biological classification.','meaning'),Q(2,'Sex education discusses…','sexual activity and reproductive health','sewer maintenance','how to sew a button','Sense 2 concerns sexual activity.','context'),Q(1,'Which phrase is natural?','biological sex','sexually biological','a sex of biology to','Biological modifies the noun sex.','grammar'),Q(1,'Sex comes from Latin sexus, referring to…','being male or female','a service appointment','a fraction of seventy','The Latin ancestor named the male/female distinction.','word-formation')]);
P('sexism','Sexism combines sex and -ism; it means the belief that one sex is inferior and the unfair treatment based on that belief.',C('sexism.s1','社会','The company revised its hiring policy after staff reported sexism in interview decisions.','员工报告面试决策中存在性别歧视后，公司修改了招聘政策。','sexism in + workplace/institution; combat sexism','名词，指性别优劣观念及由此产生的不公平对待。','biased hiring affects applicants.','社会'),M('The advert showed sexism by treating every gender fairly and giving all applicants equal opportunities.','The advert showed sexism by portraying one gender as inferior and excluding qualified applicants.','平等对待并不构成性别歧视。','meaning'),[Q(1,'Sexism is…','belief in one sex’s inferiority and unfair treatment based on it','a neutral medical classification','a form of sewerage','Sexism includes both prejudice and discriminatory treatment.','meaning'),Q(1,'A hiring process may be sexist if it…','rejects qualified applicants because of their sex','uses the same fair criteria for everyone','offers confidential health advice','Unequal treatment by sex is sexism.','context'),Q(1,'Which phrase is natural?','combat sexism in the workplace','combat sexistly in workplace','sexism to workplace combat of','In identifies the setting where sexism occurs.','grammar'),Q(1,'The suffix -ism in sexism often names…','a system of beliefs or practices','a person who serves food','a way of sewing','Sexism names an ideology and its effects.','word-formation')]);
P('sexuality','Sexuality is formed from sexual + -ity; it means how a person experiences and expresses sexual desire or the qualities society associates with being male or female.',[C('sexuality.s1','社会','The study examined how people understand and express sexuality across cultures.','这项研究考察了不同文化中人们如何理解和表达性欲与性身份。','express/explore sexuality; sexuality across cultures','名词，指个人体验性欲并表达出来的方式。','study compares experiences.','社会'),C('sexuality.s2','社会','The book examines how ideas about sexuality shape social roles.','这本书探讨了关于性别特质的观念如何塑造社会角色。','ideas about sexuality; sexuality and social roles','也可指社会与男性或女性身份相关联的特质。','social concepts influence roles.','社会')],M('The study of sexuality described how people express desire, but claimed the term means only the legal arrangement of sewer pipes.','The study of sexuality examined how people experience and express sexual desire and identity.','sewer pipes与sexuality所指的个人经验或社会性别观念无关。','meaning'),[Q(1,'A study of sexuality may examine…','how people experience and express sexual desire','how sewers carry waste water','how a shaman repairs a settee','Sexuality sense 1 concerns desire and its expression.','meaning'),Q(2,'Ideas about sexuality can be studied in relation to…','social roles linked to being male or female','the color of a serrated leaf','the seventieth floor','Sense 2 concerns societal qualities and roles.','context'),Q(1,'Which phrase is natural?','express one’s sexuality','express sexualness to sexuality','sexuality expressingly one','Express is a common verb with sexuality.','grammar'),Q(1,'The suffix -ity in sexuality forms…','an abstract noun','a person who performs an action','a past-tense verb','Sexuality names a quality or domain of experience.','word-formation')]);
P('sexually','Sexually is formed from sexual + -ly; it means with regard to sexual activity, attraction, or biological sex.',C('sexually.s1','健康','The clinic offers testing and advice about sexually transmitted infections.','诊所提供有关性传播感染的检测和咨询。','sexually transmitted; sexually active','副词表示与性行为、性吸引或生理性别有关。','health service addresses transmission.','健康'),M('The leaflet described a sexually transmitted infection, but said it spreads only through reading a book.','The leaflet described an infection that can be transmitted through sexual contact.','sexually transmitted指通过性接触传播，不是阅读书籍。','meaning'),[Q(1,'Sexually transmitted infections are associated with…','transmission through sexual contact','sewer overflow','a seafloor cable','Sexually marks the route or domain of transmission.','meaning'),Q(1,'Which sentence uses sexually correctly?','The study looks at sexually active adults.','The study sexually looks adults active.','The study looks sexual at adultsly.','Sexually modifies active.','grammar'),Q(1,'A clinic discussing sexually transmitted infections is discussing…','health risks related to sexual activity','the number of seasonal jobs','a serviceable shoe','This adverb indicates the relevant sexual-health domain.','context'),Q(1,'Sexually is formed from sexual plus…','-ly','-ness','-er','The suffix -ly makes the adverb.','word-formation')]);
P('shabby','Shabby has an uncertain deeper origin; it describes something old and in poor condition or, figuratively, treatment that is unfair and dishonourable.',[C('shabby.s1','外观','The hotel looked shabby, with peeling paint and worn carpets.','这家酒店看起来破旧，油漆剥落，地毯也磨损了。','shabby clothes/furniture/room','形容词，表示陈旧、破败或维护不佳。','visible wear.','外观'),C('shabby.s2','行为','It was shabby of the company to deny the workers their agreed leave.','公司拒绝员工已商定的休假，做法很不光彩。','a shabby trick/treatment; shabby of + person','也表示不公平、不诚实或不体面的行为。','unfair treatment.','行为')],M('The hotel looked shabby because every room was newly renovated and perfectly maintained.','The hotel looked shabby because the paint peeled and the carpets were worn.','全面翻新且维护完好与破旧相反。','meaning'),[Q(1,'A shabby hotel is…','old and in poor condition','newly renovated and spotless','a server storing web pages','Shabby sense 1 describes worn condition.','meaning'),Q(2,'Shabby treatment of workers is…','unfair or dishonourable','careful and generous','a type of seasonal weather','The figurative sense describes unworthy treatment.','context'),Q(1,'Which phrase is natural?','shabby furniture','shabbily furniture','a shabby of furniture','Shabby is an adjective modifying furniture.','grammar'),Q(1,'If a company denies agreed leave unfairly, its conduct is…','shabby','serviceable','serpentine','The action is unfair and dishonourable.','meaning')]);
P('shack','Shack is an informal word of uncertain deeper origin; it means a roughly built small building used for living or storage.',C('shack.s1','居住','The family sheltered from the rain in a small wooden shack beside the field.','一家人在田边的一间小木棚里躲雨。','a wooden/roadside shack; live in a shack','名词，指粗糙搭建、供居住或存放物品的小屋。','rough structure offers shelter.','居住'),M('The family called the shack a rough small building, but it was actually a polished ten-storey office tower.','The family sheltered in a roughly built small cabin.','十层精装写字楼不是粗陋小屋。','distinction'),[Q(1,'A shack is…','a small roughly made building','a formal court session','a large luxury tower','Shack describes a simple, roughly built structure.','meaning'),Q(1,'A wooden shack beside a field might be used for…','shelter or storage','underwater breathing','screening a film','The source sense allows living or storage.','context'),Q(1,'Which phrase is natural?','live in a shack','live a shack at','shackly live in','In identifies the building occupied.','grammar'),Q(1,'The deeper origin of shack is…','uncertain','definitely Latin for saw','from Greek for writing','The word’s earlier derivation is not confidently known.','word-formation')]);
P('shackle','Shackle comes from Old English sceacul, a fetter or bond; it is a metal restraint for wrists or ankles, or a verb meaning restrain or limit freedom.',[C('shackle.s1','历史','The guards removed the prisoner’s shackles after the hearing.','听证会后，守卫取下了囚犯的镣铐。','put/remove shackles on + person','名词，指锁住手腕或脚踝的金属环。','metal restraints removed.','历史'),C('shackle.s2','社会','Outdated rules shackled the small firms and prevented them from expanding.','过时的规定束缚了小公司，阻止它们扩张。','shackle someone/something; be shackled by + rule','动词，指用镣铐锁住，或比喻限制自由。','rules restrict growth.','社会')],M('The guard shackled the prisoner by removing every restraint and allowing the prisoner to walk freely.','The guard shackled the prisoner by fastening metal restraints around the wrists.','移除束缚、让人自由活动不是shackle。','meaning'),[Q(1,'A shackle on a prisoner is…','a metal band restraining a wrist or ankle','a seat with a back and arms','a server connection','Shackle sense 1 is a physical restraint.','meaning'),Q(2,'Rules that shackle a company…','limit its freedom to act','help it expand without limits','serve it dinner','The verb has a figurative sense of restricting freedom.','context'),Q(1,'Which phrase is natural?','shackled by outdated rules','shackled at rules out of by','shackling rules to company','By introduces the restrictions causing the limitation.','grammar'),Q(1,'Which sentence uses shackle figuratively?','Debt shackled the family’s plans.','The guard removed the metal shackle.','The server shackle was made of steel.','Debt limits the plans rather than physically restraining them.','meaning')]);
P('shade','Shade is from Old English sceadu “shadow, darkness”; it means a dark area, a light-reducing cover, a type or nuance of colour, or the act of protecting from light.',[C('shade.s1','自然','We sat in the shade beneath the large oak tree.','我们坐在大橡树下的阴凉处。','in/under the shade; a patch of shade','名词，指因遮挡阳光而形成的较暗区域。','tree blocks direct light.','自然'),C('shade.s2','家居','She pulled down the window shade to reduce glare on the screen.','她拉下窗帘遮光，减轻屏幕眩光。','a window/lamp shade; pull down a shade','名词，指减弱光线的罩或帘。','cover dims light.','家居'),C('shade.s3','艺术','The painter used several shades of blue to show depth in the water.','画家用几种不同深浅的蓝色表现水的层次。','a shade of + colour; shades of meaning','名词，指颜色种类或细微差异。','tones vary.','艺术'),C('shade.s4','通用','She shaded her eyes with one hand while looking toward the bright window.','她用一只手遮住眼睛，望向明亮的窗户。','shade one’s eyes; shade something from + light','动词，表示遮挡直射光线、保护某物。','hand blocks light.','通用')],M('She shaded her eyes by staring directly at the bright sun with both hands lowered.','She shaded her eyes by raising one hand to block the sunlight.','遮眼应阻挡强光，而不是直视太阳。','meaning'),[Q(1,'Sitting in the shade means sitting…','where sunlight is blocked','inside a sewer','under a computer setting','Shade sense 1 is a dark area protected from sun.','meaning'),Q(2,'A window shade is used to…','reduce the amount of light entering','make the room brighter at noon','set a table','This sense is a cover or blind.','context'),Q(3,'Several shades of blue are…','different kinds or tones of blue','several blue chairs','a group of servers','Shade can mean a variety of a colour.','meaning'),Q(4,'She shaded her eyes by…','blocking direct light with her hand','looking straight into the sun','setting aside her sunglasses','Shade as a verb means protect from direct light.','meaning')]);
P('shadow','From Old English sceaduwe, related to shade; shadow is a dark shape caused by blocked light, a small amount or gloomy influence, or the act of following someone closely.',[C('shadow.s1','自然','The tree cast a long shadow across the path at sunset.','日落时，树在小路上投下一道长长的影子。','cast/throw a shadow; in someone’s shadow','名词，指物体挡光后形成的暗形。','light blocked by tree.','自然'),C('shadow.s2','比喻','A shadow of doubt remained after the company released its explanation.','公司发布解释后，仍留有一丝疑虑。','a shadow of + doubt/sadness; a shadow over + event','名词也可指极少量，或给情境带来阴郁的因素。','small amount of doubt persists.','比喻'),C('shadow.s3','工作','The trainee shadowed the nurse for a week to learn the ward routine.','实习生跟随护士一周，学习病房日常工作。','shadow someone at work; job shadowing','动词，指紧跟某人以观察并学习其工作。','trainee follows professional.','工作')],M('The tree cast a shadow even though no object blocked the light and the area stayed uniformly bright.','The tree cast a shadow because it blocked the sunlight from part of the path.','没有物体挡光就不会形成阴影。','meaning'),[Q(1,'A tree’s shadow is…','a dark shape formed when it blocks light','a beam of unblocked sunlight','a seasonal work schedule','Shadow sense 1 is an area without direct light.','meaning'),Q(2,'A shadow of doubt means…','a small amount of uncertainty remains','there is absolutely no uncertainty','someone is physically following a nurse','This phrase uses shadow figuratively for a slight amount.','context'),Q(3,'A trainee shadowed the nurse to…','follow and observe her work','cast a dark shape on the ward','replace the nurse permanently','Shadow as a verb can mean follow to learn a job.','meaning'),Q(1,'Which phrase is natural?','cast a long shadow','cast shadowing longly','shadow a cast of long','Cast a shadow is the standard collocation.','collocation')]);
P('shady','Shady is formed from shade, ultimately Old English sceadu “shadow,” plus the adjective suffix -y; it describes protection from sunlight and, figuratively, doubtful conduct.',[C('shady.s1','户外','We ate lunch beneath a shady tree during the hottest part of the afternoon.','下午最热的时候，我们在一棵能遮阴的树下吃午饭。','a shady tree/spot; sit in a shady place','形容词，表示有阴凉、能遮挡阳光。','tree provides shade.','户外')],M('They chose the shady side of the street because it was fully exposed to the midday sun.','They chose the shady side of the street because it was protected from the midday sun.','shady表示有阴凉，完全暴晒与之相反。','meaning'),[Q(1,'A shady place is one that…','is protected from direct sunlight','has no shadow anywhere','is always underwater','Shady sense 1 describes a place with shade.','meaning'),Q(1,'Which afternoon picnic spot is shady?','under a broad tree','on a bare sunlit roof','inside a sealed mine shaft','The tree blocks much of the direct sun.','context'),Q(1,'Which phrase is natural?','a shady garden','a shadily garden','a shadeful gardenly','Shady is an adjective that can modify garden.','grammar'),Q(1,'In “a shady business deal,” shady most likely means…','morally doubtful','cool and protected from sunlight','made of tree branches','The adjective also has a figurative sense of suspicious conduct.','meaning')]);
P('shaft','From Old English sceaft “shaft, pole,” a Germanic word; a shaft is a long narrow bar, a vertical passage, or a beam of light.',[C('shaft.s1','器材','The golf club’s steel shaft was replaced after it bent during the tournament.','高尔夫球杆的钢杆在比赛中弯曲后被换掉了。','the shaft of a tool/club','名词，指工具或机器的一根细长杆。','long narrow club part.','器材'),C('shaft.s2','建筑','Workers lowered a camera down the lift shaft to inspect the cables.','工人把摄像机放进电梯井，检查里面的缆绳。','a lift/mine shaft; go down a shaft','名词，指建筑物或矿井中的垂直通道。','vertical passage inspected.','建筑'),C('shaft.s3','光线','A shaft of sunlight fell through a gap in the clouds.','一束阳光从云层的缝隙中照下来。','a shaft of light/sunlight','名词，也指一束光。','single beam through clouds.','自然')],M('The repairer replaced the golf club’s shaft, the vertical mine passage running to the surface.','The repairer replaced the golf club’s shaft, the long narrow bar that forms part of the club.','此处shaft指球杆的细长杆，不是矿井通道。','distinction'),[Q(1,'The shaft of a golf club is…','the long narrow bar joining the grip and head','the ball struck by the club','the player’s scorecard','Shaft sense 1 is a long narrow part of equipment.','meaning'),Q(2,'A lift shaft is…','a vertical passage for the lift','a beam of sunlight','a steel golf club part','This is the building-passage sense.','meaning'),Q(3,'A shaft of sunlight is…','a beam of light','a vertical elevator corridor','a metal tool handle','Sense 3 refers to a beam.','meaning'),Q(2,'Which phrase fits a building inspection?','lower a camera down the lift shaft','replace the shaft of sunlight','polish the shaft of a golf club','A lift shaft is a vertical building passage.','context')]);
P('shake','From Old English sceacan “to shake, move quickly,” from a Germanic verb; shake is a verb for rapid movement or emotional impact, and a noun for the movement or a milk drink.',[C('shake.s1','动作','Shake the jar gently so the dressing mixes without spilling.','轻轻摇一摇罐子，让调味汁混合而不洒出来。','shake something gently; shake hands','动词，表示使某物快速来回或上下移动。','jar moved back and forth.','动作'),C('shake.s2','情绪','The sudden announcement shook the staff and left many uncertain about their jobs.','突如其来的公告震动了员工，让许多人对自己的工作感到不安。','news shakes someone; shake someone’s confidence','动词，也表示使人震惊或动摇信念。','announcement causes shock.','情绪'),C('shake.s3','饮食','He ordered a chocolate shake with lunch.','他午餐时点了一杯巧克力奶昔。','a chocolate/milk shake; give it a shake','名词可指摇动，也可指奶昔。','drink ordered.','饮食')],M('She shook the jar by holding it perfectly still until the dressing separated into layers.','She shook the jar by moving it gently back and forth until the dressing mixed.','shake表示快速移动；静止不动不能完成摇晃。','meaning'),[Q(1,'To shake a jar is to…','move it quickly back and forth or up and down','leave it motionless','pour its contents into a mine','The verb describes rapid movement.','meaning'),Q(2,'The announcement shook the staff means it…','shocked or unsettled them','made them physically taller','served them a drink','Sense 2 concerns emotional impact.','context'),Q(3,'A chocolate shake is…','a milk-based drink','a metal golf-club part','a type of rock','Shake has a noun sense for a milk drink.','meaning'),Q(1,'Which phrase is natural?','shake the bottle gently','shake gently the bottle up by','shake of bottle gentle','The verb takes its object directly.','grammar')]);
P('shake-up','Shake-up combines shake and up; the informal compound uses the image of shaking things around for a major change to an organization or system.',[C('shake-up.s1','职场','After customer complaints, the board announced a shake-up of the management team.','客户投诉后，董事会宣布对管理团队进行重大调整。','a shake-up of + organization/team; a major shake-up','名词，指组织、团队或制度运作方式的重大改变。','management structure changed.','职场')],M('The board called the announcement a shake-up, although every manager kept the same role and no part of the organization changed.','The board called the reorganization a shake-up because it substantially changed the management team.','shake-up指重大调整，不是没有变化的公告。','meaning'),[Q(1,'A company shake-up is…','a major change in how it is run','a small drink made with milk','a routine unchanged for years','The source sense is a big organizational change.','meaning'),Q(1,'A board might order a shake-up after…','serious complaints reveal problems in management','the whole team has worked perfectly without change','a beam of sunlight enters the office','A shake-up can revise a team or system in response to problems.','context'),Q(1,'Which phrase is natural?','a shake-up of the department','a shake-up at departmenting up','a shaken-up of the department','Of introduces the organization being changed.','grammar'),Q(1,'The word shake-up is formed from…','shake + up','shale + up','shake + -ness','It is a compound built from the two words.','word-formation')]);
P('shale','Shale is an old geological term; its deeper origin is uncertain, so no more specific root is claimed here. It names fine-grained sedimentary rock that splits into thin sheets.',[C('shale.s1','地质','The cliff exposed layers of shale that split easily into thin, flat pieces.','峭壁露出一层层页岩，很容易裂成薄而平的碎片。','layers of shale; shale splits into sheets','名词，指容易裂成薄片的细粒沉积岩。','rock breaks into sheets.','地质')],M('The geologist identified the shale because the rock was coarse-grained granite that could not split into layers.','The geologist identified the shale because it was fine-grained rock that split into thin layers.','页岩是细粒、易裂成薄片的沉积岩，不是粗粒花岗岩。','distinction'),[Q(1,'Shale is a kind of…','fine-grained sedimentary rock','soft drink','vertical mine passage','The source defines shale as sedimentary rock.','meaning'),Q(1,'A geologist can recognize shale when it…','splits into thin, flat sheets','forms a sweet liquid','shakes rapidly in a jar','Its tendency to split into sheets is characteristic.','context'),Q(1,'Which phrase is natural?','layers of shale','shale of layeredly','a shaleful layer of','Shale commonly appears in layers.','collocation'),Q(1,'The deeper etymology of shale is…','uncertain','certainly from the word shake','a transparent Latin compound','The available history does not establish a definite deeper origin.','word-formation')]);
P('shall','From Old English sceal, the first- and third-person form of a Germanic verb meaning “owe” or “be obliged”; shall is used with I/we for the future and in questions offering or seeking advice.',[C('shall.s1','日常','I shall send you the revised schedule before the end of the day.','我会在今天结束前把修改后的日程发给你。','I/we shall + base verb','情态动词，常与 I 或 we 连用表示将来。','speaker states future action.','日常'),C('shall.s2','交际','Shall we take the earlier train or wait for the next one?','我们是乘较早的一班火车，还是等下一班？','Shall we + base verb?','情态动词也用于征求建议或提出共同安排。','speaker asks for a joint decision.','交际')],M('I shall to send the schedule tonight.','I shall send the schedule tonight.','shall后接动词原形，不加to。','grammar'),[Q(1,'In “I shall send it,” shall helps express…','a future action by the speaker','a past action by someone else','a completed noun phrase','The source sense uses shall with I or we for the future.','meaning'),Q(2,'“Shall we leave now?” usually…','asks for advice or proposes a joint action','states that the speakers already left','describes a type of rock','This question uses the advice/suggestion sense.','context'),Q(1,'Choose the standard construction.','We shall meet at noon.','We shall to meet at noon.','We shall meeting at noon.','A modal is followed by the base form without to.','grammar'),Q(2,'Which sentence asks the group to decide together?','Shall we order dinner now?','I shall order dinner tomorrow.','They left after dinner.','Shall we is a common way to suggest a shared action.','meaning')]);
P('shallow','From Old English sceald “shallow”; its more remote origin is uncertain. Shallow describes little depth, limited thought or feeling, and can be a noun for shallow water.',[C('shallow.s1','自然','The stream is shallow near the bank, so the children can see the stones below.','溪流靠岸处很浅，孩子们能看见水下的石头。','shallow water; a shallow stream','形容词，表示水或其他空间不深。','bottom visible near bank.','自然'),C('shallow.s2','评价','The review called the film’s characters shallow because none had believable motives.','影评人说电影角色肤浅，因为没有一个人的动机可信。','a shallow person/argument/character','形容词也表示思想、感情或内容缺乏深度。','characters lack depth.','评价'),C('shallow.s3','航海','The boat slowed before entering the shallows near the island.','船在驶入岛边的浅水区前减慢了速度。','the shallows; run aground in shallow water','名词，指水中的浅滩或浅水区。','boat approaches shallow area.','航海')],M('The stream was shallow, so its bottom lay far below the water and could not be seen.','The stream was shallow, so its bottom was close to the surface and clearly visible.','shallow表示水浅，河底离水面近。','meaning'),[Q(1,'A shallow stream has…','little depth','an extremely deep channel','no water at all','Shallow means not deep.','meaning'),Q(2,'A shallow character in a film may…','lack serious thought or convincing feelings','live only in shallow water','always be honest and complex','The second adjective sense concerns a lack of depth in thought or feeling.','context'),Q(3,'The shallows are…','shallow areas of water','deep underground tunnels','metal parts of a tool','Shallow has a noun sense for a shallow water area.','meaning'),Q(1,'Which phrase is natural?','a shallow river','a shallowly river','a shallowness river','Shallow is the adjective before a noun.','grammar')]);
P('shallowly','Shallowly is formed from shallow + the adverb suffix -ly; it means not far down, and can describe work or ideas lacking depth.',[C('shallowly.s1','施工','The fence posts were set shallowly, so the first strong wind made them lean.','栅栏柱埋得太浅，第一阵强风就把它们吹歪了。','set/bury something shallowly','副词，表示位置或深度不深。','posts have little depth underground.','施工')],M('The fence posts were shallowly buried six metres below the surface.','The fence posts were shallowly buried only a few centimetres below the surface.','shallowly表示埋得不深，六米深与此不符。','meaning'),[Q(1,'Posts set shallowly are…','not placed far below the surface','buried at a great depth','painted in several colours','Shallowly describes limited depth.','meaning'),Q(1,'Why might a shallowly set fence post lean?','It has too little depth for firm support.','It is buried much too deeply.','It is made from shale.','Limited depth can make the post unstable.','context'),Q(1,'Choose the natural placement.','The roots spread shallowly through the dry soil.','The roots spread shallow the through soilly.','The roots shallowly spread throughly.','Shallowly modifies the verb spread.','grammar'),Q(1,'Shallowly is formed by adding…','-ly to shallow','-ness to shallow','up to shake','The adverb suffix -ly forms shallowly.','word-formation')]);
P('shallowness','Shallowness is formed from shallow + -ness, which makes an adjective into a noun; it is lack of depth in water, soil, ideas, or character.',[C('shallowness.s1','文学','Readers criticized the shallowness of the plot because every conflict was solved in a single scene.','读者批评情节缺乏深度，因为每个冲突都在一个场景里解决了。','the shallowness of + plot/argument/character','名词，表示水、土层、思想或性格缺少深度。','plot lacks development.','文学')],M('The reviewer praised the shallowness of the novel because its characters developed through nuanced conflicts.','The reviewer criticized the shallowness of the novel because its characters lacked depth.','人物复杂成长并非情节或人物缺乏深度的例子。','meaning'),[Q(1,'Shallowness of a plot means…','a lack of depth or development','that every event occurs underwater','the story has many detailed layers','The noun names a lack of depth.','meaning'),Q(1,'Which criticism points to shallowness?','The characters never face complex choices.','The river is too deep to cross.','The novel has a long list of chapters.','Simple, undeveloped characters can make a plot shallow.','context'),Q(1,'Which phrase is natural?','the shallowness of the argument','the shallowly of the argument','the shallowness argumently','Of links the noun to what lacks depth.','grammar'),Q(1,'The suffix -ness changes shallow into…','a noun naming a quality or state','a future modal','a past-tense verb','-ness commonly forms abstract nouns from adjectives.','word-formation')]);
P('sham','Sham is recorded in English from the seventeenth century; its deeper origin is uncertain. As a noun it is a deceptive fake, and as an adjective it means not genuine.',[C('sham.s1','鉴别','The museum discovered that the signed certificate was a sham and removed it from the display.','博物馆发现这张签名证书是赝品，于是将它从展览中撤下。','a sham; expose/reveal a sham','名词，指伪装成真的、用来欺骗别人的东西。','fake certificate exposed.','鉴别'),C('sham.s2','评价','The manager offered only sham concern for the staff while ignoring their safety complaints.','经理对员工只是假装关心，却无视他们关于安全的投诉。','sham concern/support; a sham + noun','形容词，表示不真实、只是装出来的。','concern is feigned.','评价')],M('The dealer admitted the painting was a sham, although it was an authentic original with a documented history.','The dealer admitted the painting was a sham, a fake presented as an original.','赝品与有完整来源的真迹不能同时成立。','distinction'),[Q(1,'A sham certificate is…','a fake presented as genuine','an original document verified by experts','a session of a court','Sham as a noun means a deceptive fake.','meaning'),Q(2,'Sham concern means concern that is…','pretended rather than genuine','deeply sincere and consistently shown','caused by a shady tree','The adjective sense describes something not genuine.','context'),Q(1,'Which phrase is natural?','expose a sham','shamly expose a','expose of shamness','Sham is a noun in the phrase expose a sham.','grammar'),Q(2,'In “a sham apology,” sham most nearly means…','not sincere or genuine','carefully written by hand','related to a shamanic ritual','The adjective marks the apology as merely pretending.','meaning')]);
P('shaman','Shaman entered English through Russian from Evenki saman, a term for a ritual specialist; a shaman is understood in the relevant tradition to mediate between people and spirits.',[C('shaman.s1','人类学','In the account, the shaman led a healing ritual and prayed for the patient’s recovery.','在这段记述中，萨满主持了疗愈仪式，并为患者康复祈祷。','a shaman performs/leads a ritual; shamanic practice','名词，指在某些传统中通过仪式沟通人和神灵的人。','ritual specialist leads ceremony.','人类学')],M('The village called the shaman its ritual specialist, but the person’s only task was repairing sewer pipes.','The village called the shaman its ritual specialist, who led ceremonies believed to connect people with spirits.','管道维修本身不符合此处萨满的仪式职能。','distinction'),[Q(1,'A shaman is a ritual specialist associated with…','mediating between people and spirits','maintaining a sewer network','designing golf clubs','The source sense centers on ritual mediation.','meaning'),Q(1,'In the account, why does the shaman lead a healing ritual?','The tradition connects the specialist’s ceremonies with healing.','The shaman is replacing a plumber.','The word means a sham certificate.','The context presents a culturally situated ritual role.','context'),Q(1,'Which phrase is natural?','the shaman led a ritual','the shaman was ritualing a','the ritual shamanly led','A shaman can lead a ritual.','grammar'),Q(1,'Shaman reached English through…','Russian, from an Evenki term','Old English sceaduwe','Latin severitas','Its documented borrowing route is through Russian from Evenki.','word-formation')]);
P('shamble','Shamble is a verb of uncertain deeper history; it describes walking slowly with short, dragging, unsteady steps.',[C('shamble.s1','动作','After the long hike, he shambled back to the cabin in muddy boots.','长途徒步后，他穿着沾泥的靴子拖着步子走回小屋。','shamble along/across/back; shamble into a room','动词，指缓慢、拖沓而不稳地走。','tired uneven walk.','动作')],M('After the long hike, he shambled back to the cabin by sprinting smoothly at full speed.','After the long hike, he shambled back to the cabin with slow, dragging steps.','全速平稳冲刺不符合shamble所指的拖步慢行。','meaning'),[Q(1,'If someone shambles, the person…','walks slowly with dragging, unsteady steps','runs quickly with an even stride','sits completely still','Shamble describes a slow, shuffling walk.','meaning'),Q(1,'Why might a tired hiker shamble to a cabin?','The hiker is moving slowly and unsteadily.','The hiker is sprinting in a race.','The hiker is asking for a meeting suggestion.','Fatigue can make the walk slow and dragging.','context'),Q(1,'Which sentence uses shamble naturally?','He shambled across the yard in oversized boots.','He shambled the letter into a formal memo.','He shambled the water until it boiled.','A person can shamble across a place.','grammar'),Q(1,'The deeper origin of shamble is…','uncertain','definitely from the suffix -ness','a Latin word for a mine shaft','The word’s earlier history is not firmly established here.','word-formation')]);
P('shame','From Old English sceamu or scamu, a Germanic word for disgrace; shame is painful self-consciousness, a regrettable matter, or the act of making someone feel ashamed.',[C('shame.s1','情绪','She felt shame after realizing that her careless remark had hurt a colleague.','意识到自己不经意的话伤害了同事后，她感到羞愧。','feel shame; hang one’s head in shame','名词，指因做错事或出丑而产生的不安感。','speaker regrets hurtful remark.','情绪'),C('shame.s2','评价','It is a shame that the outdoor concert was cancelled just before sunset.','户外音乐会偏偏在日落前取消，真是遗憾。','it is a shame (that…); what a shame','名词，也指令人惋惜的事。','cancelled event is regrettable.','评价'),C('shame.s3','行为','The public report shamed the agency into correcting its misleading figures.','这份公开报告使该机构感到羞愧，最终更正了误导性数据。','shame someone into doing something','动词，指使某人感到羞愧，促使其改正。','criticism prompts correction.','行为')],M('It is a shame that the concert was cancelled, but here shame means the musician felt guilty for causing the cancellation.','It is a shame that the concert was cancelled; it is simply an unfortunate situation.','此处it is a shame表示遗憾，不表示说话者因过错而羞愧。','distinction'),[Q(1,'Feeling shame after a hurtful remark is…','feeling bad about having done something wrong','being proud of harming someone','walking with dragging steps','Shame sense 1 is uncomfortable self-consciousness after wrongdoing.','meaning'),Q(2,'“It is a shame the concert was cancelled” means…','the cancellation is regrettable','the speaker caused it and feels guilty','the concert was a fake','This expression uses shame for something one is sorry about.','context'),Q(3,'The report shamed the agency into correcting its figures means…','it made the agency feel ashamed and act','it gave the agency a decorative shape','it invited the agency to a session','Shame someone into doing something describes pressure through embarrassment.','meaning'),Q(1,'Which phrase is natural?','feel shame after a mistake','feel shamefully after a mistake','shame a feelingly mistake','Feel takes the noun shame.','grammar')]);
P('shameful','Shameful is formed from shame + -ful, “full of” or “characterized by”; it describes conduct deserving shame because it is wrong, cruel, or dishonest.',[C('shameful.s1','行为','The report described the deliberate waste of donated food as shameful.','报告称故意浪费捐赠食品的行为令人不齿。','a shameful act/decision; shameful of + person','形容词，表示行为错误、残忍或不诚实，理应受到谴责。','deliberate waste condemned.','行为')],M('The report called the charity’s careful distribution of every donated meal shameful, although no food was wasted.','The report called the charity’s deliberate waste of donated meals shameful.','妥善分发食物不是浪费或不当行为。','meaning'),[Q(1,'A shameful decision is one that…','deserves criticism because it is wrong or dishonest','is admirable and entirely fair','is simply old and worn','Shameful describes conduct deserving shame.','meaning'),Q(1,'Which action could reasonably be called shameful?','Knowingly hiding evidence that would protect an innocent person','Sharing donated food fairly','Apologizing after admitting a mistake','Cruel or dishonest conduct can deserve shame.','context'),Q(1,'Which phrase is natural?','a shameful waste of food','a shamefully waste of food','a shameful of wastedly food','Shameful is an adjective modifying waste.','grammar'),Q(1,'The suffix -ful in shameful contributes the sense…','characterized by or full of shame','without shame','a person who walks slowly','-ful forms an adjective from the noun shame.','word-formation')]);
P('shameless','Shameless is formed from shame + -less, “without”; it describes someone who shows no embarrassment about behaviour others consider wrong.',[C('shameless.s1','评价','The shameless driver blamed pedestrians for a crash caused by his own reckless speeding.','那名无耻的司机把自己鲁莽超速造成的事故归咎于行人。','a shameless lie/attempt; shameless about + behaviour','形容词，指做了别人认为不妥的事却毫不难为情。','driver refuses embarrassment.','评价')],M('She was shameless about the lie because she apologized immediately and admitted she had been wrong.','She was ashamed of the lie because she apologized immediately and admitted she had been wrong.','承认错误并道歉表现出羞愧，与shameless相反。','distinction'),[Q(1,'A shameless excuse is offered…','without embarrassment about behaviour others see as wrong','only after a sincere apology','to describe a shallow river','Shameless means not embarrassed by questionable conduct.','meaning'),Q(1,'Which person acts shamelessly?','A manager lies to staff and boasts that no one can challenge him.','A manager admits a lie and apologizes.','A manager feels regret and corrects the record.','Boasting about misconduct shows no embarrassment.','context'),Q(1,'Which phrase is natural?','a shameless attempt to avoid blame','a shamelessly attempt avoid blame','a shameful-less attempt blame','Shameless is an adjective before attempt.','grammar'),Q(1,'The suffix -less in shameless means…','without','full of','in the past','-less means lacking or without shame.','word-formation')]);
P('shampoo','Shampoo was borrowed from Hindi cā̃po, the imperative of cā̃pnā “to press or massage,” through Anglo-Indian English; it names hair-washing liquid and the act of washing hair with it.',[C('shampoo.s1','日常','After the swim, she used a mild shampoo to wash the chlorine from her hair.','游泳后，她用温和的洗发水洗掉头发上的氯。','use/apply shampoo; shampoo one’s hair','名词，指洗发用的皂液；也可指用它洗头。','liquid cleans hair.','日常')],M('After swimming, she used shampoo to polish the metal shaft of the golf club.','After swimming, she used shampoo to wash the chlorine from her hair.','shampoo用于洗头，不是金属抛光剂。','meaning'),[Q(1,'Shampoo is primarily used to…','wash hair','join cloth with needle and thread','carry waste water','The source sense identifies shampoo as hair-washing liquid.','meaning'),Q(1,'After swimming, why might someone shampoo their hair?','To wash away chlorine and other residue','To set a fence post shallowly','To make a fake certificate','Shampoo can name the act of washing hair with it.','context'),Q(1,'Which phrase is natural?','apply shampoo to wet hair','apply a shampooing to wetly hair','shampooing apply of hair wet','Shampoo commonly appears with apply or use.','collocation'),Q(1,'The word entered English through a borrowing from…','Hindi, via Anglo-Indian English','Old English sceald','Latin sexus','The documented route is from Hindi through Anglo-Indian English.','word-formation')]);
P('shank','From Old English sceanca “leg,” a Germanic word; shank is the long narrow part of a tool or nail, or the lower part of a leg between knee and ankle.',[C('shank.s1','工具','The screw would not hold because its shank was too short for the two boards.','这颗螺钉的杆部太短，无法固定两块木板。','the shank of a screw/tool','名词，指工具、钉子或设备上连接两端的细长部分。','narrow screw part too short.','工具'),C('shank.s2','动物','The vet found a small cut on the horse’s front shank.','兽医发现马的前小腿上有一道小伤口。','the shank of the leg; a horse’s shank','名词也指人或动物膝盖与脚踝之间的小腿部分。','vet examines lower leg.','动物')],M('The screw’s shank is the broad flat head that turns against the screwdriver.','The screw’s shank is the long narrow section that extends below its head.','螺钉头不是连接部件的细长杆部。','distinction'),[Q(1,'The shank of a screw is…','its long narrow section below the head','the slot in its head','the wood around it','Shank sense 1 names the narrow connecting part.','meaning'),Q(2,'A horse’s shank is…','the part of its leg between knee and ankle','the nail holding a shoe','a shaft of sunlight','Shank sense 2 refers to the lower leg.','context'),Q(1,'Which phrase is natural?','the shank of the drill bit','the shank of drillingly bit','the shanked of drill bit','Of identifies the tool part.','grammar'),Q(2,'Where would a vet inspect an animal’s shank?','on its lower leg','inside a mine lift shaft','at the end of its tail','The animal-leg sense is between knee and ankle.','meaning')]);
P('shanty','Shanty is a name for a roughly built cabin or shack; its deeper origin is uncertain, and no disputed derivation is asserted.',[C('shanty.s1','居住','The crew repaired the leaking roof of the small shanty beside the railway.','工人们修好了铁路旁那间小棚屋漏雨的屋顶。','a small/wooden shanty; live in a shanty','名词，指粗陋搭建的小屋或窝棚。','rough cabin has leaking roof.','居住')],M('The crew called the shanty a rough cabin, but it was actually a newly built marble palace.','The crew repaired the rough wooden cabin that served as their shanty.','豪华大理石宫殿不符合shanty所指的粗陋小屋。','distinction'),[Q(1,'A shanty is…','a roughly made small cabin','a formal parliament session','a long metal golf-club part','Shanty means a rough cabin or shack.','meaning'),Q(1,'Workers beside a railway might sleep in…','a shanty','a shaft of light','a milk shake','A shanty can serve as a simple shelter.','context'),Q(1,'Which phrase is natural?','a wooden shanty beside the tracks','a woodenly shanty beside trackful','a shanty of woodenly beside','Wooden modifies the noun shanty.','grammar'),Q(1,'The deeper origin of shanty is…','uncertain','certainly from Latin for shame','a suffix meaning “without”','No single deeper derivation is claimed here.','word-formation')]);
P('shape','From Old English gesceap “creation, form,” related to scieppan “to create”; shape is an object’s outline, its condition, or the act of forming or influencing something.',[C('shape.s1','外观','The children cut the paper into the shape of a crescent moon.','孩子们把纸剪成新月的形状。','in the shape of + noun; a round/irregular shape','名词，指物体的外部形态。','outline resembles crescent.','外观'),C('shape.s2','健康','With regular walks, her knee is back in good shape.','坚持散步后，她的膝盖状况恢复良好。','in good/bad shape; get into shape','名词也可表示某人或某物的状况。','condition improved.','健康'),C('shape.s3','发展','Early lessons shaped his interest in designing buildings.','早期课程塑造了他对建筑设计的兴趣。','shape someone’s views/future; shape something into + form','动词，指使某物成形或影响其发展。','lessons influence interest.','发展')],M('The children cut the paper into the shape of a crescent by leaving it as a perfect square.','The children cut the paper into the shape of a crescent by trimming its corners.','正方形没有新月形的轮廓。','meaning'),[Q(1,'The shape of an object is its…','outer form or outline','state of emotional embarrassment','history of its raw materials','Shape sense 1 concerns form.','meaning'),Q(2,'If someone is in good shape, they are…','in good condition','a deceptive fake','inside a vertical passage','This phrase uses shape for condition.','context'),Q(3,'Early experiences can shape a person’s future by…','influencing how it develops','giving it a geometric outline only','making it a shallow water area','The verb includes influencing development.','meaning'),Q(1,'Which phrase is natural?','a bowl in the shape of a flower','a bowl shapefully of flower','a shape of bowl to flowered','In the shape of introduces the resemblance.','grammar')]);
P('shapeless','Shapeless combines shape, from Old English gesceap “form,” with the suffix -less “without”; it describes something lacking a clear outline or pleasing form.',[C('shapeless.s1','服装','The old sweater had stretched at the elbows and hung in a shapeless mass.','旧毛衣的肘部已经撑大，整件衣服松垮得没有样子。','a shapeless coat/garment; shapeless mass','形容词，表示没有清楚轮廓或不美观。','worn garment lost outline.','服装')],M('The coat was shapeless because it had a sharply tailored waist and crisp, well-defined outline.','The coat was shapeless because it hung loosely without a clear outline.','剪裁合身、轮廓分明与shapeless相反。','distinction'),[Q(1,'A shapeless coat…','lacks a clear outline or pleasing form','has a sharply defined silhouette','is made only from shale','Shapeless describes a lack of clear form.','meaning'),Q(1,'Which item might be described as shapeless?','an old sweater stretched into a loose mass','a carefully tailored jacket with a defined waist','a new set of seven keys','A stretched garment may lose its outline.','context'),Q(1,'Which phrase is natural?','a shapeless grey mass','a shapelessly grey mass','a shape-lessly mass grey','Shapeless is an adjective modifying mass.','grammar'),Q(1,'The suffix -less in shapeless means…','without','full of','capable of','-less means lacking shape.','word-formation')]);
})();
